const finite=(x,label)=>{if(!Number.isFinite(x))throw new Error(`${label} must be finite`);return x;};
const positive=(x,label)=>{finite(x,label);if(x<=0)throw new Error(`${label} must be positive`);return x;};
export const secondsToFrame=(seconds,fps)=>Math.round(finite(seconds,'seconds')*positive(fps,'fps'));
export const frameToSeconds=(frame,fps)=>finite(frame,'frame')/positive(fps,'fps');
export const secondsToSample=(seconds,sampleRate)=>Math.round(finite(seconds,'seconds')*positive(sampleRate,'sampleRate'));
export const sampleToSeconds=(sample,sampleRate)=>finite(sample,'sample')/positive(sampleRate,'sampleRate');
/** Planned grid, not measurement. n is absolute, so rounded step lengths never accumulate. */
export function beatGrid({bpm,offset=0,start=0,end,fps}){
  positive(bpm,'bpm');finite(offset,'offset');finite(start,'start');finite(end,'end');if(end<=start)throw new Error('empty interval');
  const first=Math.ceil((start-offset)*bpm/60),last=Math.ceil((end-offset)*bpm/60)-1;
  if(last-first>1000000)throw new Error('beat grid too large');
  return Array.from({length:Math.max(0,last-first+1)},(_,i)=>{const index=first+i,at=offset+index*60/bpm;return {index,at,time_basis:'planned',...(fps?{frame:secondsToFrame(at,fps)}:{})};});
}
export const tempoCandidates=bpm=>{positive(bpm,'bpm');return [bpm/2,bpm,bpm*2];};
/** Explicit measured beat records only. Fixed events are always kept unchanged. */
export function snapEvents(events,beats,{tolerance=.06,sourceHash}={}){
  finite(tolerance,'tolerance');if(tolerance<0||!sourceHash)throw new Error('need non-negative tolerance and source hash');
  if(beats.some((b,i)=>!Number.isFinite(b.at)||b.at<0||b.time_basis!=='measured'||b.source_hash!==sourceHash||!b.evidence||(i&&b.at<=beats[i-1].at)))throw new Error('beats must be ordered, measured, and tied to the current source');
  return events.map(e=>{
    finite(e.at,'event.at');if(!e.allow_snap||!beats.length)return {...e,snap_status:'kept'};
    const nearest=beats.reduce((a,b)=>Math.abs(b.at-e.at)<Math.abs(a.at-e.at)?b:a),delta=nearest.at-e.at,allowed=e.tolerance??tolerance;
    if(!Number.isFinite(allowed)||allowed<0)throw new Error('bad event tolerance');
    if(Math.abs(delta)>allowed|| (e.min_at!==undefined&&nearest.at<e.min_at)||(e.max_at!==undefined&&nearest.at>e.max_at))return {...e,snap_status:'outside_tolerance'};
    return {...e,planned_at:e.at,at:nearest.at,time_basis:'measured',source_hash:sourceHash,evidence:nearest.evidence,beat_id:nearest.id,delta,snap_status:'snapped'};
  });
}
export function sfxStart(contactAt,peakOffset){finite(contactAt,'contact');finite(peakOffset,'peakOffset');if(peakOffset<0)throw new Error('negative peak offset');const at=contactAt-peakOffset;return {at,preRoll:Math.max(0,-at),needsPreRoll:at<0};}

import React,{useLayoutEffect,useRef} from 'react';
import {AbsoluteFill,cancelRender} from 'remotion';
import {keyedRandom,loopPhase} from '../motion-core.mjs';
import {clamp01,positive,smooth,unit} from '../remotion-kit/time';
export type ReadingZone={x:number;y:number;width:number;height:number;padding?:number;feather?:number;floor?:number};
/** Pixel coordinates. 0 means suppressed, 1 means unrestricted. */
export function readingAttenuation(x:number,y:number,zones:ReadingZone[]=[]){
  return zones.reduce((weight,z)=>{
    const p=z.padding??24,f=Math.max(1,z.feather??80),floor=clamp01(z.floor??.08);
    const dx=Math.max(z.x-p-x,0,x-z.x-z.width-p),dy=Math.max(z.y-p-y,0,y-z.y-z.height-p);
    return Math.min(weight,floor+(1-floor)*smooth(Math.hypot(dx,dy)/f));
  },1);
}
export const ReadingZoneMask=readingAttenuation;
export type Draw=(g:CanvasRenderingContext2D,t:number,width:number,height:number)=>void;
export const BackgroundCanvas:React.FC<{t:number;width:number;height:number;draw:Draw;dpr?:number;style?:React.CSSProperties}>=({t,width,height,draw,dpr=1,style})=>{
  positive(width);positive(height);if(dpr<=0||dpr>3)throw new Error('explicit DPR must be 0..3');
  const ref=useRef<HTMLCanvasElement>(null);
  useLayoutEffect(()=>{
    try{
      const canvas=ref.current;if(!canvas)throw new Error('Canvas not mounted');
      canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);
      const g=canvas.getContext('2d');if(!g)throw new Error('Canvas 2D unavailable');
      g.setTransform(dpr,0,0,dpr,0,0);g.clearRect(0,0,width,height);g.save();draw(g,t,width,height);g.restore();
    }catch(error){cancelRender(error instanceof Error?error:new Error(String(error)));}
  },[t,width,height,draw,dpr]); // Synchronous draw before paint; no asynchronous assets here.
  return <canvas ref={ref} style={{position:'absolute',width,height,...style}}/>;
};
type FieldProps={t:number;width:number;height:number;seed?:string;zones?:ReadingZone[];color?:string;period?:number};
export const FlowField:React.FC<FieldProps & {lines?:number;steps?:number;stepLength?:number}>=({t,width,height,seed='flow',zones=[],color='#7899aa',period=12,lines=100,steps=35,stepLength=6})=>{
  if(lines<1||lines>2000||steps<1||steps>200)throw new Error('invalid flow budget');positive(stepLength);
  return <BackgroundCanvas t={t} width={width} height={height} draw={(g,time,w,h)=>{
    const phase=loopPhase(time,period)*Math.PI*2;g.strokeStyle=color;g.lineWidth=1.2;
    for(let i=0;i<lines;i++){
      let x=keyedRandom(seed,`${i}:x`)*w,y=keyedRandom(seed,`${i}:y`)*h;
      for(let j=0;j<steps;j++){
        const angle=1.8*Math.sin(x/w*5+Math.sin(phase))+1.3*Math.cos(y/h*4+Math.cos(phase));
        const nx=x+Math.cos(angle)*stepLength,ny=y+Math.sin(angle)*stepLength;
        g.globalAlpha=.23*readingAttenuation((x+nx)/2,(y+ny)/2,zones);g.beginPath();g.moveTo(x,y);g.lineTo(nx,ny);g.stroke();x=nx;y=ny;
      }
    }
  }}/>;
};
export const ParticleAtmosphere:React.FC<FieldProps & {count?:number;mode?:'drift'|'orbit'|'gather';targets?:[number,number][];gatherAt?:number;gatherDuration?:number;radius?:number}>=({t,width,height,seed='particles',zones=[],color='#aacadd',period=14,count=240,mode='drift',targets,gatherAt=0,gatherDuration=1.2,radius=2})=>{
  if(count<1||count>20000||!Number.isInteger(count))throw new Error('particle count must be integer 1..20000');positive(radius);
  if(mode==='gather'&&(!targets||targets.length<count))throw new Error('gather requires one explicit target per particle');
  return <BackgroundCanvas t={t} width={width} height={height} draw={(g,time,w,h)=>{
    const phase=loopPhase(time,period)*Math.PI*2;g.fillStyle=color;
    for(let i=0;i<count;i++){
      const rx=keyedRandom(seed,`${i}:x`),ry=keyedRandom(seed,`${i}:y`),a=keyedRandom(seed,`${i}:phase`)*Math.PI*2;
      let x=rx*w+Math.sin(phase+a)*24,y=ry*h+Math.cos(phase+a)*18;
      if(mode==='orbit'){const r=Math.sqrt(rx)*Math.min(w,h)*.6;x=w/2+Math.cos(phase+a)*r;y=h/2+Math.sin(phase+a)*r*.55;}
      if(mode==='gather'){const delay=keyedRandom(seed,`${i}:delay`)*.25,p=smooth(unit(time,gatherAt+delay,gatherAt+delay+gatherDuration));x+= (targets![i][0]-x)*p;y+=(targets![i][1]-y)*p;}
      g.globalAlpha=(.15+.5*ry)*readingAttenuation(x,y,zones);g.beginPath();g.arc(x,y,radius*(.4+ry),0,Math.PI*2);g.fill();
    }
  }}/>;
};
export const DotGrid:React.FC<FieldProps & {spacing?:number;focus?:[number,number];eventAt?:number;amplitude?:number}>=({t,width,height,zones=[],color='#91a2b2',spacing=42,focus=[width/2,height/2],eventAt=0,amplitude=6})=>{
  positive(spacing);if(width*height/(spacing*spacing)>40000)throw new Error('dot grid budget exceeded');
  return <BackgroundCanvas t={t} width={width} height={height} draw={(g,time,w,h)=>{
    g.fillStyle=color;const tau=time-eventAt;
    for(let y=spacing/2;y<h;y+=spacing)for(let x=spacing/2;x<w;x+=spacing){
      const dx=x-focus[0],dy=y-focus[1],r=Math.hypot(dx,dy),u=tau-r/500;
      const wave=u<0?0:Math.sin(u*14)*Math.exp(-u*4)*amplitude;
      const px=x+wave*dx/Math.max(1,r),py=y+wave*dy/Math.max(1,r);
      g.globalAlpha=.45*readingAttenuation(px,py,zones);g.beginPath();g.arc(px,py,1.5,0,Math.PI*2);g.fill();
    }
  }}/>;
};
function noise(x:number,y:number,seed:string){
  const ix=Math.floor(x),iy=Math.floor(y),u=smooth(x-ix),v=smooth(y-iy);
  const a=keyedRandom(seed,`${ix},${iy}`),b=keyedRandom(seed,`${ix+1},${iy}`),c=keyedRandom(seed,`${ix},${iy+1}`),d=keyedRandom(seed,`${ix+1},${iy+1}`);
  return (a+(b-a)*u)*(1-v)+(c+(d-c)*u)*v;
}
export const NoiseGradient:React.FC<FieldProps & {colors?:[[number,number,number],[number,number,number]];cell?:number;octaves?:number}>=({t,width,height,seed='noise',zones=[],period=20,colors=[[15,24,37],[61,92,113]],cell=24,octaves=3})=>{
  if(cell<4||octaves<1||octaves>6)throw new Error('invalid noise resolution');
  return <BackgroundCanvas t={t} width={width} height={height} draw={(g,time,w,h)=>{
    const phase=loopPhase(time,period)*Math.PI*2,cols=Math.ceil(w/cell),rows=Math.ceil(h/cell),c=document.createElement('canvas');c.width=cols;c.height=rows;const small=c.getContext('2d');if(!small)throw new Error('noise canvas unavailable');
    const pixels=small.createImageData(cols,rows);
    for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){
      let n=0,total=0;for(let k=0;k<octaves;k++){const a=.5**k;n+=a*noise(x/cols*3*2**k+Math.cos(phase),y/rows*3*2**k+Math.sin(phase),seed+':'+k);total+=a;}
      const p=n/total*readingAttenuation(x*cell,y*cell,zones),i=(y*cols+x)*4;
      for(let j=0;j<3;j++)pixels.data[i+j]=Math.round(colors[0][j]+(colors[1][j]-colors[0][j])*p);pixels.data[i+3]=255;
    }small.putImageData(pixels,0,0);g.imageSmoothingEnabled=true;g.drawImage(c,0,0,w,h);
  }}/>;
};
export const LightSweep:React.FC<{progress:number;opacity?:number;angle?:number;color?:string}>=({progress,opacity=.2,angle=-20,color='#ffffff'})=><AbsoluteFill style={{overflow:'hidden',pointerEvents:'none'}}><AbsoluteFill style={{left:`${-80+180*clamp01(progress)}%`,width:'60%',transform:`rotate(${angle}deg)`,opacity,background:`linear-gradient(to right,transparent,${color},transparent)`}}/></AbsoluteFill>;
export const Vignette:React.FC<{strength?:number}>=({strength=.4})=><AbsoluteFill style={{pointerEvents:'none',background:`radial-gradient(ellipse at center,transparent 35%,rgba(0,0,0,${clamp01(strength)}) 100%)`}}/>;
export const Grain:React.FC<FieldProps & {count?:number;opacity?:number;drawingsPerSecond?:number}>=({t,width,height,seed='grain',zones=[],count=1800,opacity=.06,drawingsPerSecond=12})=>{
  if(count<0||count>50000)throw new Error('grain budget exceeded');positive(drawingsPerSecond);
  return <BackgroundCanvas t={t} width={width} height={height} draw={(g,time,w,h)=>{const pose=Math.floor(time*drawingsPerSecond);for(let i=0;i<count;i++){const x=keyedRandom(seed,`${pose}:${i}:x`)*w,y=keyedRandom(seed,`${pose}:${i}:y`)*h;g.globalAlpha=opacity*readingAttenuation(x,y,zones);g.fillStyle=i%2?'#fff':'#000';g.fillRect(x,y,1.5,1.5);}}}/>;
};

import React from 'react';
import {AbsoluteFill} from 'remotion';
import {camera2D,cameraCenterForAnchor,keyedRandom} from '../motion-core.mjs';
import {clamp01,finite,positive,smooth} from '../remotion-kit/time';
export {camera2D,cameraCenterForAnchor};
export type CameraState={center:[number,number];zoom:number;rotation:number;tiltX?:number;tiltY?:number};
export type CameraKey=CameraState & {at:number;stop?:boolean};
export const CameraRig:React.FC<{t:number;camera:(t:number)=>CameraState;width:number;height:number;children:React.ReactNode;screen?:React.ReactNode;perspective?:number}>=({t,camera,width,height,children,screen,perspective=1400})=>{
  const c=camera(t);positive(c.zoom);positive(perspective);
  return <AbsoluteFill style={{overflow:'hidden'}}><AbsoluteFill style={{perspective,transformStyle:'preserve-3d'}}><AbsoluteFill style={{transformOrigin:'0 0',transform:`translate(${width/2}px,${height/2}px) scale(${c.zoom}) rotate(${c.rotation}rad) rotateX(${c.tiltX??0}rad) rotateY(${c.tiltY??0}rad) translate(${-c.center[0]}px,${-c.center[1]}px)`}}>{children}</AbsoluteFill></AbsoluteFill><AbsoluteFill style={{pointerEvents:'none'}}>{screen}</AbsoluteFill></AbsoluteFill>;
};
const hermite=(a:number,b:number,va:number,vb:number,span:number,u:number)=>(2*u**3-3*u*u+1)*a+(u**3-2*u*u+u)*span*va+(-2*u**3+3*u*u)*b+(u**3-u*u)*span*vb;
/** Shared tangents at intermediate stations; duplicate a pose at a later time to hold. */
export function cameraPath(keys:CameraKey[]){
  if(!keys.length)throw new Error('empty camera path');
  keys.forEach((k,i)=>{finite(k.at);positive(k.zoom);[...k.center,k.rotation].forEach(n=>finite(n));if(i&&k.at<=keys[i-1].at)throw new Error('camera keys must increase');});
  const value=(k:CameraKey)=>[...k.center,Math.log(k.zoom),k.rotation,k.tiltX??0,k.tiltY??0];
  const values=keys.map(value);
  const tangents=keys.map((k,i)=>values[i].map((_,axis)=>{
    if(k.stop||i===0||i===keys.length-1)return 0;
    return (values[i+1][axis]-values[i-1][axis])/(keys[i+1].at-keys[i-1].at);
  }));
  return (t:number):CameraState=>{
    if(t<=keys[0].at)return keys[0];if(t>=keys[keys.length-1].at)return keys[keys.length-1];
    const b=keys.findIndex(k=>k.at>t),a=b-1,span=keys[b].at-keys[a].at,u=(t-keys[a].at)/span;
    const v=values[a].map((x,j)=>hermite(x,values[b][j],tangents[a][j],tangents[b][j],span,u));
    return {center:[v[0],v[1]],zoom:Math.exp(v[2]),rotation:v[3],tiltX:v[4],tiltY:v[5]};
  };
}
export const ParallaxLayer:React.FC<{camera:CameraState;depth:number;width:number;height:number;children:React.ReactNode}>=({camera,depth,width,height,children})=>{
  if(depth<0||!Number.isFinite(depth))throw new Error('depth must be non-negative');positive(camera.zoom);
  return <AbsoluteFill style={{transformOrigin:'50% 50%',transform:`translate(${(width/2-camera.center[0])*depth}px,${(height/2-camera.center[1])*depth}px) rotate(${camera.rotation*depth}rad) scale(${camera.zoom**depth})`}}>{children}</AbsoluteFill>;
};
export function shake(t:number,{start=0,duration=.5,amplitude=8,frequency=18,seed='shake'}={}){
  positive(duration);positive(frequency);const elapsed=t-start;
  if(elapsed<0||elapsed>=duration)return [0,0] as [number,number];
  const n=elapsed*frequency,i=Math.floor(n),p=smooth(n-i),envelope=smooth(elapsed/.04)*(1-elapsed/duration)**2;
  const sample=(axis:string)=>{const a=keyedRandom(seed,`${axis}:${i}`)*2-1,b=keyedRandom(seed,`${axis}:${i+1}`)*2-1;return (a+(b-a)*p)*amplitude*envelope;};
  return [sample('x'),sample('y')] as [number,number];
}
export const RackFocus:React.FC<{focus:number;depth:number;maxBlur?:number;breathing?:number;children:React.ReactNode}>=({focus,depth,maxBlur=14,breathing=.015,children})=>{
  const distance=clamp01(Math.abs(focus-depth));
  return <AbsoluteFill style={{filter:`blur(${distance*Math.max(0,maxBlur)}px)`,transform:`scale(${1+distance*breathing})`}}>{children}</AbsoluteFill>;
};
export function dollyZoomFov(distance:number,referenceDistance:number,referenceFovRadians:number){
  positive(distance);positive(referenceDistance);
  if(referenceFovRadians<=0||referenceFovRadians>=Math.PI)throw new Error('fov must be between 0 and pi');
  return 2*Math.atan(referenceDistance*Math.tan(referenceFovRadians/2)/distance);
}
export function orbit(t:number,{center=[0,0] as [number,number],radius=300,speed=.25,phase=0}={}){
  const angle=phase+t*speed;return {x:center[0]+radius*Math.cos(angle),y:center[1]+radius*Math.sin(angle),heading:angle+Math.PI/2};
}

/** Project-authored time adapter; no renderer, media, network, player or RAF is started. */
export function createCanvasContract({canvas, width, height, duration, fps=30, supersample=1, draw, resources=Promise.resolve()}) {
  for (const [key, value] of Object.entries({width,height,duration,fps,supersample})) {
    if (!Number.isFinite(value) || value <= 0) throw new RangeError(`${key} must be positive and finite`);
  }
  if (![width,height,supersample].every(Number.isInteger)) throw new RangeError('dimensions and supersample must be integers');
  if (typeof draw !== 'function') throw new TypeError('draw must be a function');
  const ctx=canvas.getContext('2d');
  if (!ctx) throw new Error('Canvas 2D context unavailable');
  canvas.width=width*supersample; canvas.height=height*supersample;
  const film={duration,fps,ready:false,error:null,seek};
  film.readyPromise=Promise.resolve(resources).then(()=>{film.ready=true;}, error=>{
    film.error=error instanceof Error ? error : new Error(String(error));
    throw film.error;
  });
  function seek(seconds) {
    if (film.error) throw film.error;
    if (!film.ready) throw new Error('Resources not ready; await readyPromise');
    if (!Number.isFinite(seconds)) throw new TypeError('seconds must be finite');
    const t=Math.max(0,Math.min(duration,seconds));
    if (typeof ctx.reset === 'function') ctx.reset(); else canvas.width=width*supersample;
    ctx.setTransform(supersample,0,0,supersample,0,0);
    ctx.save();
    try { draw({ctx,t,frame:Math.round(t*fps),width,height,fps,supersample}); }
    finally { ctx.restore(); }
    return t;
  }
  return film;
}

import React from 'react';
import {keyedRandom,springAt,steppedTime} from '../motion-core.mjs';
import {clamp01,positive,smooth,unit} from '../remotion-kit/time';
export type RigPart={id:string;parent?:string;offset:[number,number];pivot?:[number,number];angle?:(t:number)=>number;drawing:React.ReactNode};
/** SVG local coordinates; angles in radians. Pass SVG paths/groups as drawing. */
export const Rig2D:React.FC<{t:number;parts:RigPart[];width:number;height:number;origin?:[number,number]}>=({t,parts,width,height,origin=[0,0]})=>{
  const map=new Map(parts.map(p=>[p.id,p]));if(map.size!==parts.length)throw new Error('duplicate rig part');
  for(const part of parts){const seen=new Set<string>();let p:RigPart|undefined=part;while(p){if(seen.has(p.id))throw new Error('cyclic rig');seen.add(p.id);if(p.parent&&!map.has(p.parent))throw new Error('missing parent '+p.parent);p=p.parent?map.get(p.parent):undefined;}}
  const render=(p:RigPart):React.ReactNode=><g key={p.id} transform={`translate(${p.offset.join(' ')}) rotate(${(p.angle?.(t)??0)*180/Math.PI} ${(p.pivot??[0,0]).join(' ')})`}>{p.drawing}{parts.filter(c=>c.parent===p.id).map(render)}</g>;
  return <svg width={width} height={height}><g transform={`translate(${origin.join(' ')})`}>{parts.filter(p=>!p.parent).map(render)}</g></svg>;
};
export type PoseKey={at:number;values:Record<string,number>;mode?:'hold'|'linear'|'ease'};
export function poseTimeline(keys:PoseKey[],drawingsPerSecond?:number){
  if(!keys.length)throw new Error('empty poses');const fields=Object.keys(keys[0].values);
  keys.forEach((key,i)=>{if(i&&key.at<=keys[i-1].at)throw new Error('pose times must increase');if(Object.keys(key.values).length!==fields.length||fields.some(f=>!Number.isFinite(key.values[f])))throw new Error('pose fields must match');});
  return (time:number)=>{const t=drawingsPerSecond?steppedTime(time,drawingsPerSecond):time;
    if(t<=keys[0].at)return {...keys[0].values};if(t>=keys[keys.length-1].at)return {...keys[keys.length-1].values};
    const b=keys.findIndex(k=>k.at>t),a=keys[b-1],z=keys[b],raw=unit(t,a.at,z.at),p=a.mode==='hold'?0:a.mode==='linear'?raw:smooth(raw);
    return Object.fromEntries(fields.map(f=>[f,a.values[f]+(z.values[f]-a.values[f])*p]));
  };
}
export function blinkAt(t:number,seed='blink',interval=4,duration=.14){
  positive(interval);positive(duration);if(duration*3>=interval)throw new Error('blink duration exceeds interval');
  const bucket=Math.floor(t/interval),start=bucket*interval+.2+(interval-duration*3-.2)*keyedRandom(seed,bucket);
  const blink=(a:number)=>{const p=(t-a)/duration;return p<0||p>1?1:1-Math.sin(Math.PI*p)**2;};
  return Math.min(blink(start),keyedRandom(seed,`${bucket}:double`)>.88?blink(start+duration*1.5):1);
}
export const Blink:React.FC<{t:number;seed?:string;children:React.ReactNode;origin?:string}>=({t,seed='blink',children,origin='50% 50%'})=><g style={{transformBox:'fill-box',transformOrigin:origin,transform:`scaleY(${Math.max(.03,blinkAt(t,seed))})`}}>{children}</g>;
export function lookAt(eye:[number,number],target:[number,number],radiusX=4,radiusY=3):[number,number]{
  positive(radiusX);positive(radiusY);const dx=target[0]-eye[0],dy=target[1]-eye[1],length=Math.hypot(dx,dy);return length<1e-6?[0,0]:[dx/length*radiusX,dy/length*radiusY];
}
export const LookAt:React.FC<{eye:[number,number];target:[number,number];radius?:number;color?:string}>=({eye,target,radius=3,color='#111'})=>{const [x,y]=lookAt(eye,target);return <circle cx={eye[0]+x} cy={eye[1]+y} r={radius} fill={color}/>;};
export function walkPose(t:number,{speed=110,period=.8,ground=600,lift=36,stance=.6}={}){
  positive(period);if(speed<0||stance<=0||stance>=1)throw new Error('invalid gait');const stride=speed*period,bodyX=t*speed;
  const foot=(offset:number)=>{const phase=t/period+offset,cycle=Math.floor(phase),p=phase-cycle,contact=p<stance,u=clamp01((p-stance)/(1-stance));return {x:(cycle-offset)*stride+(contact?0:stride*smooth(u)),y:ground-(contact?0:lift*Math.sin(Math.PI*u)),contact,phase:p};};
  return {bodyX,bob:Math.sin(t/period*Math.PI*4)*6,left:foot(0),right:foot(.5)};
