  for (let i = 0; i < times.length; i++) {
    const t0 = i ? times[i - 1] : 0;
    if (lt >= times[i]) x = edges[i];
    else {
      x = (i ? edges[i - 1] : 0) + (edges[i] - (i ? edges[i - 1] : 0)) * clamp01((lt - t0) / (times[i] - t0));
