  const k = Math.min(1, Math.max(0, (sizePx - 40) / 120));
  return -0.01 - 0.025 * k;
};

/** Line-height: tight for display, open for CJK. */
export const leading = (role: Role, cjk = false) => (cjk ? (role === "display" ? 1.25 : 1.6) : role === "display" ? 1.02 : role === "title" ? 1.12 : 1.45);

