/** Pure numeric helpers. No DOM, network, media, wall clock or hidden simulation state. */
const finite = (x, label='value') => { if (!Number.isFinite(x)) throw new Error(`${label} must be finite`); return x; };
const positive = (x, label) => { finite(x,label); if(x<=0)throw new Error(`${label} must be positive`); return x; };
export const clamp = (x,a=0,b=1) => { finite(x); if(a>b)throw new Error('reversed clamp'); return Math.min(b,Math.max(a,x)); };
export const lerp = (a,b,p) => a+(b-a)*p;
export const progress = (t,start,end) => { [t,start,end].forEach(x=>finite(x)); if(end<=start)throw new Error('empty time range'); return clamp((t-start)/(end-start)); };
export const secondsToFrame = (seconds,fps,mode='nearest') => {
  finite(seconds); positive(fps,'fps');
  const f={nearest:Math.round,start:Math.floor,end:Math.ceil}[mode];
  if(!f)throw new Error('rounding mode'); return f(seconds*fps);
};
export const frameToSeconds = (frame,fps) => finite(frame)/positive(fps,'fps');
export const steppedTime = (t,drawingsPerSecond=12) => Math.floor(finite(t)*positive(drawingsPerSecond,'drawing rate'))/drawingsPerSecond;
export const loopPhase = (t,duration) => {positive(duration,'duration');return ((finite(t)%duration)+duration)%duration/duration;};
export const easeOutCubic = p => 1-(1-clamp(p))**3;
export const easeInOut = p => {p=clamp(p);return p*p*(3-2*p);};
export function cubicBezier(x1,y1,x2,y2){
  [x1,y1,x2,y2].forEach(x=>finite(x)); if(x1<0||x1>1||x2<0||x2>1)throw new Error('Bezier x controls outside [0,1]');
  const q=(u,a,b)=>3*(1-u)**2*u*a+3*(1-u)*u*u*b+u*u*u;
  return p=>{p=clamp(p);if(p===0||p===1)return p;let lo=0,hi=1;for(let n=0;n<48;n++){const u=(lo+hi)/2;if(q(u,x1,x2)<p)lo=u;else hi=u;}return q((lo+hi)/2,y1,y2);};
}
/** Unit step x(0)=0, x'(0)=velocity, target 1. coefficient damping c, stiffness k, mass m. */
export function springAt(t,{stiffness=140,damping=20,mass=1,velocity=0}={}){
  finite(t);positive(stiffness,'stiffness');positive(mass,'mass');finite(damping);finite(velocity);
  if(damping<0)throw new Error('negative damping'); if(t<=0)return 0;
  const w=Math.sqrt(stiffness/mass), z=damping/(2*Math.sqrt(stiffness*mass));
  if(Math.abs(z-1)<1e-7)return 1+(-1+(velocity-w)*t)*Math.exp(-w*t);
  if(z<1){const wd=w*Math.sqrt(1-z*z);return 1+Math.exp(-z*w*t)*(-Math.cos(wd*t)+(velocity-z*w)/wd*Math.sin(wd*t));}
  const r1=-w*(z-Math.sqrt(z*z-1)),r2=-w*(z+Math.sqrt(z*z-1));
  const a=(velocity+r2)/(r1-r2),b=-1-a;return 1+a*Math.exp(r1*t)+b*Math.exp(r2*t);
}
/** Stable per-key pseudo random; no call-order dependency. Not cryptographic. */
export function keyedRandom(seed,key){let h=2166136261;for(const c of `${seed}:${key}`){h^=c.codePointAt(0);h=Math.imul(h,16777619);}h^=h>>>16;h=Math.imul(h,0x7feb352d);h^=h>>>15;h=Math.imul(h,0x846ca68b);h^=h>>>16;return (h>>>0)/4294967296;}
export function keyed(t,keys,{ease=easeInOut,log=false}={}){
  finite(t);if(keys.length<1)throw new Error('empty keys');
  keys.forEach(([at,v],i)=>{finite(at);finite(v);if(i&&at<=keys[i-1][0])throw new Error('keys must increase');if(log&&v<=0)throw new Error('log values must be positive');});
  if(t<=keys[0][0])return keys[0][1];if(t>=keys.at(-1)[0])return keys.at(-1)[1];
  const i=keys.findIndex(k=>k[0]>t),a=keys[i-1],b=keys[i],p=ease(progress(t,a[0],b[0]));
  return log?Math.exp(lerp(Math.log(a[1]),Math.log(b[1]),p)):lerp(a[1],b[1],p);
}
export function camera2D(point,{center=[0,0],screen=[0,0],zoom=1,rotation=0}={}){
  positive(zoom,'zoom');const x=point[0]-center[0],y=point[1]-center[1],c=Math.cos(rotation),s=Math.sin(rotation);
  return [screen[0]+zoom*(c*x-s*y),screen[1]+zoom*(s*x+c*y)];
}
export function cameraCenterForAnchor(anchor,screenTarget,{screen=[0,0],zoom=1,rotation=0}={}){
  positive(zoom,'zoom');const x=(screenTarget[0]-screen[0])/zoom,y=(screenTarget[1]-screen[1])/zoom,c=Math.cos(rotation),s=Math.sin(rotation);
  return [anchor[0]-(c*x+s*y),anchor[1]-(-s*x+c*y)];
}
/** Output source rectangle for cover; focal point is normalized; no image editing. */
export function coverCrop(iw,ih,bw,bh,focus=[.5,.5],zoom=1){
  [iw,ih,bw,bh,zoom].forEach(x=>positive(x,'dimension/zoom'));if(zoom<1)throw new Error('cover zoom below 1');
  const scale=Math.max(bw/iw,bh/ih)*zoom,sw=bw/scale,sh=bh/scale;
  return {x:clamp(focus[0]*iw-sw/2,0,iw-sw),y:clamp(focus[1]*ih-sh/2,0,ih-sh),width:sw,height:sh,scale};
}
export function visibleBoxFraction(subject,crop){
  positive(subject.width,'subject width');positive(subject.height,'subject height');
  const w=Math.max(0,Math.min(subject.x+subject.width,crop.x+crop.width)-Math.max(subject.x,crop.x));
  const h=Math.max(0,Math.min(subject.y+subject.height,crop.y+crop.height)-Math.max(subject.y,crop.y));
  return w*h/(subject.width*subject.height);
}
export function pointAlongPolyline(points,p){
  if(points.length<2)throw new Error('path needs two points');p=clamp(p);
  const lens=points.slice(1).map((b,i)=>Math.hypot(b[0]-points[i][0],b[1]-points[i][1]));
  let d=p*lens.reduce((a,b)=>a+b,0);for(let i=0;i<lens.length;i++){if(d<=lens[i]&&lens[i]>0)return [lerp(points[i][0],points[i+1][0],d/lens[i]),lerp(points[i][1],points[i+1][1],d/lens[i])];d-=lens[i];}return [...points.at(-1)];
}
/** Exact endpoint wave: no discontinuous nonzero cosine at impact. */
export const contactRing = (t,contact,{amplitude=8,decay=7,frequency=38}={}) => t<contact?0:amplitude*Math.exp(-decay*(t-contact))*Math.sin(frequency*(t-contact));
export function formationPoint(t,element,group){
  const tau=t-element.delay,p=group.path(tau),a=group.heading(tau),s=group.scale(tau),[x,y]=element.offset;
  const envelope=group.flutterEnvelope(tau),dy=(group.wave||0)*Math.sin((group.k||0)*x-(group.omega||0)*t);
  const flutter=envelope*(Math.sin(t*element.frequency+element.phase));
  return [p[0]+s*(Math.cos(a)*x-Math.sin(a)*(y+dy)),p[1]+s*(Math.sin(a)*x+Math.cos(a)*(y+dy))+flutter];
}

import React from 'react';
import {Audio,Sequence,staticFile,cancelRender} from 'remotion';
import {frameAt,positive,smooth} from './time';
export type VoiceWindow={start:number;end:number};
export type Track={id:string;file:string;start:number;end:number;gain:number;trimSeconds?:number;role:'voice'|'music'|'sfx'|'ambience'};
export function duckGain(t:number,voices:VoiceWindow[],floor=.25,attack=.12,release=.3){
  if(floor<0||floor>1)throw new Error('duck floor must be 0..1');positive(attack);positive(release);
  let activity=0;
  for(const v of voices){if(v.end<=v.start)throw new Error('empty voice window');
    const a=t<v.start?smooth((t-v.start+attack)/attack):t<=v.end?1:1-smooth((t-v.end)/release);
    activity=Math.max(activity,a);
  }return 1-(1-floor)*activity;
}
export function sfxTrack(eventAt:number,peakOffset:number,duration:number,track:Omit<Track,'start'|'end'|'role'>):Track{
  if(!Number.isFinite(peakOffset)||peakOffset<0||!Number.isFinite(eventAt))throw new Error('invalid SFX event or peak offset');
  const start=eventAt-peakOffset;
  if(start<0)throw new Error('SFX begins before zero: design pre-roll or choose another source');
  positive(duration);return {...track,start,end:start+duration,role:'sfx'};
}
/** All times are global seconds; use at composition root, not inside a scene Sequence. */
export const AudioTracks:React.FC<{tracks:Track[];fps:number;voices?:VoiceWindow[];duckFloor?:number}>=({tracks,fps,voices=[],duckFloor=.25})=><>{tracks.map(track=>{
  const from=frameAt(track.start,fps),to=frameAt(track.end,fps),trim=frameAt(track.trimSeconds??0,fps);
  if(from<0||to<=from||trim<0||!Number.isFinite(track.gain)||track.gain<0)throw new Error(`invalid audio track ${track.id}`);
  return <Sequence key={track.id} from={from} durationInFrames={to-from} name={track.id}><Audio src={staticFile(track.file)} trimBefore={trim} volume={localFrame=>track.gain*(track.role==='music'?duckGain((localFrame+from)/fps,voices,duckFloor):1)} onError={error=>cancelRender(error)}/></Sequence>;
})}</>;

import React from 'react';
import {AbsoluteFill,useCurrentFrame,useVideoConfig} from 'remotion';
export type CaptionCue={id:string;start:number;end:number;lines:string[]};
export type CaptionLike={text:string;startMs:number;endMs:number;timestampMs:number|null;confidence:number|null};
export function cueFromCaption(c:CaptionLike,id:string,lines:string[]):CaptionCue{return {id,start:c.startMs/1000,end:c.endMs/1000,lines};}
/** Explicit semantic lines; no automatic Chinese whitespace segmentation. */
export const Captions:React.FC<{cues:CaptionCue[];family:string;size?:number;globalFromFrame?:number;bottom?:number;color?:string}>=({cues,family,size=48,globalFromFrame=0,bottom=86,color='#fff'})=>{
  const f=useCurrentFrame(),{fps}=useVideoConfig(),t=(f+globalFromFrame)/fps;
  const active=cues.filter(c=>t>=c.start&&t<c.end);
  if(active.length>1)throw new Error('Overlapping caption cues: merge or resolve explicitly');
  const c=active[0];if(!c)return null;
  if(c.lines.length<1||c.lines.length>2)throw new Error('Caption requires one or two explicit lines');
  return <AbsoluteFill style={{justifyContent:'flex-end',alignItems:'center',padding:`0 5% ${bottom}px`,pointerEvents:'none'}}><div style={{maxWidth:'100%',fontFamily:family,fontSize:size,lineHeight:1.4,fontSynthesis:'none',textAlign:'center',color,background:'rgba(0,0,0,.7)',padding:'.15em .45em',boxSizing:'border-box'}}>{c.lines.map((line,i)=><div key={i} style={{whiteSpace:'pre'}}>{line}</div>)}</div></AbsoluteFill>;
};

import {useEffect,useState} from 'react';
import {cancelRender,continueRender,delayRender,staticFile} from 'remotion';
export type FontSpec={family:string;file:string;weight?:string;style?:string;stretch?:string};
const loads=new Map<string,Promise<void>>();
const gates=new Map<string,{promise:Promise<void>;ready:boolean}>();
function load(spec:FontSpec){
  const key=JSON.stringify(spec);let promise=loads.get(key);
  if(!promise){promise=(async()=>{
    const face=new FontFace(spec.family,`url(${JSON.stringify(staticFile(spec.file))})`,{weight:spec.weight??'400',style:spec.style??'normal',...(spec.stretch?{stretch:spec.stretch}:{})});
    document.fonts.add(await face.load());await document.fonts.ready;
  })();loads.set(key,promise);promise.catch(()=>loads.delete(key));}
  return promise;
}
/** Mount once above SceneStack with a stable manifest. Change its key to replace fonts. */
export function useFonts(specs:FontSpec[]){
  const signature=JSON.stringify(specs);
  const [initial]=useState(()=>signature);
  if(initial!==signature)throw new Error('Font manifest changed: remount the font gate with a new key');
  let entry=gates.get(signature);
  if(!entry){
    const handle=delayRender('local font files');
    const gate={ready:false,promise:Promise.resolve()};
    gate.promise=Promise.all(specs.map(load)).then(()=>{gate.ready=true;continueRender(handle);}).catch(error=>{cancelRender(error instanceof Error?error:new Error(String(error)));});
    gates.set(signature,gate);entry=gate;
  }
  const gate=entry;
  const [ready,setReady]=useState(gate.ready);
  useEffect(()=>{
    let active=true;
    gate.promise.then(()=>{if(active&&gate.ready)setReady(true);});
    // A StrictMode cleanup must not release an unfinished shared font load.
    return ()=>{active=false;};
  },[gate]);
  return ready;
}
/** This measures layout; it does NOT verify cmap coverage or true variable axes. */
export function measureCN(text:string,font:string){
  if(typeof document==='undefined')throw new Error('font measurement requires browser');
  if(!document.fonts.check(font,text))throw new Error('font is not ready');
  const g=document.createElement('canvas').getContext('2d');if(!g)throw new Error('Canvas 2D unavailable');
  g.font=font;return g.measureText(text);
}

# Remotion 时间轴与分层骨架

独立编写的接入源码，目标本机Remotion4.0.537。已核读声明/相关源码，不等于编译、运行或媒体验收；本次只修改，未执行这些动作。不含运行依赖、字体、图片或音频。

## 接入

复制所需implementations及相对依赖，保持目录关系，沿用目标工程React/Remotion设置。Task含fps、width、height、phase、scenes、events、可选duration。场景 `{id,start,end}` 为绝对秒，start排序、end严格递增；最多两场重叠。根层处理字体、屏幕字幕与音轨，世界内容交给SceneStack。

```tsx
const Shot:React.FC<{scene:SceneSpec}>=({scene})=>{
 const {local,global}=useTime(frameAt(scene.start,task.fps));
 const events=eventTimeline(task.events,'planned');
 const p=events.progressBetween('E_BEGIN','E_END',global,smooth);
 return <World t={local} progress={p}/>;
};
// task、World、fontManifest、cues、tracks由实际项目提供。
const Film=()=>{
 const ready=useFonts(fontManifest);
 if(!ready)return null;
 return <>
  <SceneStack scenes={task.scenes} fps={task.fps} renderScene={scene=><Shot scene={scene}/>}/>
  <Captions cues={cues} family="ProjectSans"/>
  <AudioTracks tracks={tracks} fps={task.fps} voices={voiceWindows}/>
 </>;
};
```

renderScene回调本身不要调用Hook；返回组件，让Hook在Sequence内执行。Root.example.tsx是两块色板的接线入口，调用registerRoot有副作用，只在指定入口使用；不是已完成动画。

| 文件 | 职责 |
|---|---|
| time.ts | frameAt/secondsAt、半开区间inRange、局部全局换算、unit/smooth、frameRange、schedule、useTime |
| timeline.ts | Task/Event/SceneSpec、layoutScenes、taskDuration、eventTimeline |
| Scene.tsx | Sequence内局部帧加绝对fromFrame一次；入/出transform独立包装 |
| SceneStack.tsx | 场景绝对边界转Sequence，presentations键如S01->S02；默认crossfade及不透明底色 |
| fonts.ts | FontFace、共享promise和一次性render等待；measureCN |
| random.ts | 核心keyedRandom(seed,key)，对象id固定 |
| audio.tsx | AudioTracks、duckGain、sfxTrack；根时间轴分轨 |
| captions.tsx | Captions、cueFromCaption；显式一/两行，毫秒转秒 |
| Root.example.tsx | Composition、calculateMetadata、registerRoot接线 |

schedule([4,4.5],[.5])为8秒；已有绝对0–4、3.5–8则直接取最大end，不再减重叠。frameRange分别round(start×fps)、round(end×fps)，禁止round每段时长再累计。duration可延长保留音尾，不能截短场景。

eventTimeline(events,basis,sourceHash?)严格选择planned或measured；返回eventAt(id)、event(id)、since(id,t)、progressBetween(a,b,t,ease)。实测需要source_hash/evidence，传当前hash可拒绝旧测量。词锚需word、occurrence、source_span。不自动测量或在时间基准之间悄悄兜底。

字体清单 `{family,file,weight?,style?,stretch?}` 的file相对public；可变字体weight范围必须真实。挂载期间清单不可改，换清单用新key。共享promise等待完成才continueRender，StrictMode清理不提前释放；失败cancelRender。document.fonts和measureCN不证明cmap、真实轴或无回退。

Track `{id,file,start,end,gain,trimSeconds?,role}` 全局秒，仅根层放一次。role为voice/music/sfx/ambience。volume回调局部帧加该轨from一次算duck；trimSeconds是源文件起点，不是时间轴偏移。sfxTrack按接触−峰值偏移放置，负起点报错。总duration覆盖尾音。

CaptionCue `{id,start,end,lines:string[]}` 显式语义断行；CaptionLike兼容text/startMs/endMs/timestampMs/confidence，可选pageBreakAfter未用于自动分页。重叠cue报错，过长单行不会自动缩字。根层globalFromFrame=0；放Sequence内就传绝对from一次。

## API核读与限制（2026-10-30）

本机声明核到：AbsoluteFill、Sequence的from/durationInFrames、useCurrentFrame、useVideoConfig、Composition、CalculateMetadataFunction、registerRoot、Audio的trimBefore/volume/onError、staticFile、Img、delayRender、continueRender、cancelRender。Caption基本结构来自本地@remotion/captions/dist/caption.d.ts。FontFace是浏览器API。没有复制官方技能文字/代码。

本机remotion/media/captions/media-utils4.0.537、three0.170.0、TypeScript5.9.3。新骨架不要求media/media-utils；包存在不代表其全部API逐一核读。未找到@remotion/transitions、@remotion/three、@react-three/fiber、@remotion/layout-utils；旧specimen的额外3D依赖仍需目标工程处理。

常见错：Sequence局部帧加offset两次；spring混用秒/帧；staticFile传F盘绝对路径；字体等待失衡超时；旧OffthreadVideo与新media接口混用；Root被当普通库import。Canvas同步绘制在layout effect完成，异步资源另外等待，不能靠固定setTimeout。

