import React, { useEffect, useMemo, useState } from "react";
import { useThree } from "@react-three/fiber";
import { ThreeCanvas } from "@remotion/three";
import { cancelRender, continueRender, delayRender } from "remotion";
import * as THREE from "three";
import { rand, type SpecimenTheme } from "./theme";

/**
 * 05 FIELD: 60,000 GPU particles in one ShaderMaterial. Every particle carries five target positions
 * (sphere shell, galaxy, text, image/logo, line) and the shader blends between them — all a pure function
 * of the uniforms, so frames render independently. World units are pixels at z = 0.
 */
export const PARTICLES = 60000;

export type FieldState = {
  stage: number; // 0 sphere · 1 galaxy · 2 text · 3 image · 4 line (fractional = morphing)
  burst: number; // outward explosion
  noise: number; // curl-ish drift amplitude (px)
  spin: number; // galaxy rotation (rad)
  point: number; // 0..1 collapse to a single point
  t: number; // time in frames
  alpha?: number;
  tiltX?: number;
  rotY?: number;
};

const VERT = /* glsl */ `
uniform float uStage, uBurst, uNoise, uSpin, uPoint, uT, uSize, uPx;
attribute vec3 aA; attribute vec3 aB; attribute vec3 aC; attribute vec3 aD; attribute vec3 aE;
attribute vec4 aRnd; attribute vec3 aCol;
varying vec3 vCol; varying float vA;
vec3 hash3(vec3 p){ p = fract(p * vec3(.1031,.1030,.0973)); p += dot(p, p.yxz + 33.33); return fract((p.xxy + p.yxx) * p.zyx) * 2.0 - 1.0; }
float vnoise(vec3 p){ vec3 i = floor(p); vec3 f = fract(p); f = f*f*(3.0-2.0*f);
  float n = mix(mix(mix(dot(hash3(i), f), dot(hash3(i+vec3(1,0,0)), f-vec3(1,0,0)), f.x),
                    mix(dot(hash3(i+vec3(0,1,0)), f-vec3(0,1,0)), dot(hash3(i+vec3(1,1,0)), f-vec3(1,1,0)), f.x), f.y),
                mix(mix(dot(hash3(i+vec3(0,0,1)), f-vec3(0,0,1)), dot(hash3(i+vec3(1,0,1)), f-vec3(1,0,1)), f.x),
                    mix(dot(hash3(i+vec3(0,1,1)), f-vec3(0,1,1)), dot(hash3(i+vec3(1,1,1)), f-vec3(1,1,1)), f.x), f.y), f.z);
  return n; }
vec3 galaxy(vec3 p){ float r = length(p.xz); float a = uSpin * (0.6 + 260.0 / (r + 90.0));
  float c = cos(a), s = sin(a); return vec3(p.x * c - p.z * s, p.y, p.x * s + p.z * c); }
vec3 target(float i){
  if (i < 0.5) return aA;
  if (i < 1.5) { vec3 g = galaxy(aB); float tx = 1.05; return vec3(g.x, g.y * cos(tx) - g.z * sin(tx), g.y * sin(tx) + g.z * cos(tx)); }
  if (i < 2.5) return aC;
  if (i < 3.5) return aD;
  return aE; }
void main(){
  float s0 = floor(uStage); float f = uStage - s0;
  float k = smoothstep(0.0, 1.0, clamp(f * 1.7 - aRnd.x * 0.7, 0.0, 1.0));
  vec3 p = mix(target(s0), target(min(s0 + 1.0, 4.0)), k);
  p *= 1.0 + uBurst * (0.35 + aRnd.y * 1.2);
  vec3 q = p * 0.0032 + vec3(0.0, 0.0, uT * 0.012) + aRnd.yzw * 3.0;
  p += uNoise * vec3(vnoise(q), vnoise(q + 17.3), vnoise(q + 41.9));
  float pk = smoothstep(0.0, 1.0, clamp(uPoint * 1.5 - aRnd.z * 0.5, 0.0, 1.0));
  p = mix(p, vec3(0.0), pk);
  vec4 mv = modelViewMatrix * vec4(p, 1.0);
  gl_Position = projectionMatrix * mv;
  gl_PointSize = uSize * (0.55 + aRnd.w * 0.9) * (uPx / -mv.z);
  vCol = aCol; vA = 0.55 + 0.45 * aRnd.y;
}`;

const FRAG = /* glsl */ `
uniform float uAlpha; varying vec3 vCol; varying float vA;
void main(){ vec2 c = gl_PointCoord - 0.5; float d = length(c); if (d > 0.5) discard;
  float a = (1.0 - smoothstep(0.08, 0.5, d)) * uAlpha * vA; gl_FragColor = vec4(vCol, a); }`;

type Targets = { text: Float32Array; image: Float32Array };

const samplePoints = (paint: (g: CanvasRenderingContext2D) => void, step = 2) => {
  const c = document.createElement("canvas");
  c.width = 1920;
  c.height = 1080;
  const g = c.getContext("2d")!;
  paint(g);
  const d = g.getImageData(0, 0, 1920, 1080).data;
  const pts: number[] = [];
  for (let y = 0; y < 1080; y += step) for (let x = 0; x < 1920; x += step) if (d[(y * 1920 + x) * 4 + 3] > 140) pts.push(x - 960, 540 - y);
  return pts;
};

const fill = (pts: number[], n: number, seed: number, depth: number) => {
  const out = new Float32Array(n * 3);
  if (!pts.length) throw new Error("Particle target is empty: verify font coverage, image alpha and dimensions");
  const m = pts.length / 2;
  for (let i = 0; i < n; i++) {
    const j = Math.floor(rand(i, seed) * m) * 2;
    out[i * 3] = (pts[j] ?? 0) + (rand(i, seed + 1) - 0.5) * 1.6;
    out[i * 3 + 1] = (pts[j + 1] ?? 0) + (rand(i, seed + 2) - 0.5) * 1.6;
    out[i * 3 + 2] = (rand(i, seed + 3) - 0.5) * depth;
  }
  return out;
};

/** Loads fonts/images and samples the text and image targets once (delayRender until ready). */
export const useFieldTargets = (text: { value: string; font: string }, imageSrc: string, imageSize: number): Targets | null => {
  const [targets, setTargets] = useState<Targets | null>(null);
  const [handle] = useState(() => delayRender("particle targets"));
  useEffect(() => {
    let alive = true;
    const img = new Image();
    const imgReady = new Promise<void>((res, rej) => {
      img.onload = () => res();
      img.onerror = () => rej(new Error(`image ${imageSrc}`));
    });
    img.crossOrigin = "anonymous";
    img.src = imageSrc;
    let settled = false;
    // delayRender 必须恰好 settle 一次：成功 continue，失败或提前卸载 cancel。
    // 漏掉任何一条，资源 404 / 字体缺字 / 中途卸载都会让 Remotion 一直等到超时。
    const settle = (error?: unknown) => {
      if (settled) return;
      settled = true;
      if (error) cancelRender(error instanceof Error ? error : new Error(String(error)));
      else continueRender(handle);
    };
    Promise.all([document.fonts.load(text.font, text.value), imgReady]).then(() => {
      if (!alive) { settle(new Error("particle targets unmounted before ready")); return; }
      const tp = samplePoints((g) => {
        g.fillStyle = "#fff";
        g.textAlign = "center";
        g.textBaseline = "middle";
        g.font = text.font;
        g.fillText(text.value, 960, 540);
      });
      const ip = samplePoints((g) => g.drawImage(img, 960 - imageSize / 2, 540 - imageSize / 2, imageSize, imageSize));
      setTargets({ text: fill(tp, PARTICLES, 31, 10), image: fill(ip, PARTICLES, 47, 14) });
      settle();
    }).catch((error) => {
      settle(error);
    });
    return () => {
      alive = false;
      settle(new Error("particle targets unmounted"));
    };
  }, [handle, imageSrc, imageSize, text.font, text.value]);
  return targets;
};

const Points: React.FC<{ th: SpecimenTheme; s: FieldState; targets: Targets; R: number }> = ({ th, s, targets, R }) => {
  const { gl } = useThree();
  const geo = useMemo(() => {
    const g = new THREE.BufferGeometry();
    const n = PARTICLES;
    const A = new Float32Array(n * 3);
    const B = new Float32Array(n * 3);
    const E = new Float32Array(n * 3);
    const rnd = new Float32Array(n * 4);
    const col = new Float32Array(n * 3);
    const cream = new THREE.Color(th.cream);
    const extra = (th.sprinkle.length ? th.sprinkle : [th.cream]).map((c) => new THREE.Color(c));
    const golden = Math.PI * (3 - Math.sqrt(5));
    const srgb = { r: 0, g: 0, b: 0 };
    for (let i = 0; i < n; i++) {
      const y = 1 - (i / (n - 1)) * 2;
      const r = Math.sqrt(1 - y * y);
      const th0 = golden * i;
      const rr = R * (1 + (rand(i, 2) - 0.5) * 0.015);
      A[i * 3] = Math.cos(th0) * r * rr;
      A[i * 3 + 1] = y * rr;
      A[i * 3 + 2] = Math.sin(th0) * r * rr;
      const arm = i % 3;
      const gr = 30 + Math.pow(rand(i, 3), 0.75) * 760;
      const ga = (arm * Math.PI * 2) / 3 + gr * 0.0065 + (rand(i, 4) - 0.5) * 0.5 * (1 - gr / 900);
      B[i * 3] = Math.cos(ga) * gr + (rand(i, 5) - 0.5) * 40;
      B[i * 3 + 1] = (rand(i, 6) - 0.5) * 60 * (1 - gr / 900);
      B[i * 3 + 2] = Math.sin(ga) * gr + (rand(i, 7) - 0.5) * 40;
      E[i * 3] = (rand(i, 8) - 0.5) * 1500;
      E[i * 3 + 1] = (rand(i, 9) + rand(i, 10) - 1) * 4;
      E[i * 3 + 2] = (rand(i, 11) - 0.5) * 30;
      rnd.set([rand(i, 12), rand(i, 13), rand(i, 14), rand(i, 15)], i * 4);
      const c = rand(i, 16) < 0.8 ? cream : extra[Math.floor(rand(i, 17) * extra.length)];
      c.getRGB(srgb, THREE.SRGBColorSpace);
      col.set([srgb.r, srgb.g, srgb.b], i * 3);
    }
    g.setAttribute("position", new THREE.BufferAttribute(new Float32Array(n * 3), 3));
    g.setAttribute("aA", new THREE.BufferAttribute(A, 3));
    g.setAttribute("aB", new THREE.BufferAttribute(B, 3));
    g.setAttribute("aC", new THREE.BufferAttribute(targets.text, 3));
    g.setAttribute("aD", new THREE.BufferAttribute(targets.image, 3));
    g.setAttribute("aE", new THREE.BufferAttribute(E, 3));
    g.setAttribute("aRnd", new THREE.BufferAttribute(rnd, 4));
    g.setAttribute("aCol", new THREE.BufferAttribute(col, 3));
    g.boundingSphere = new THREE.Sphere(new THREE.Vector3(), 1e5);
    return g;
  }, [th, targets, R]);
  const mat = useMemo(
    () =>
      new THREE.ShaderMaterial({
        vertexShader: VERT,
        fragmentShader: FRAG,
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
        uniforms: {
          uStage: { value: 0 },
          uBurst: { value: 0 },
          uNoise: { value: 0 },
          uSpin: { value: 0 },
          uPoint: { value: 0 },
          uT: { value: 0 },
          uSize: { value: 2.6 },
          uPx: { value: 2015 },
          uAlpha: { value: 1 },
        },
      }),
    [],
  );
  const u = mat.uniforms;
  u.uStage.value = s.stage;
  u.uBurst.value = s.burst;
  u.uNoise.value = s.noise;
  u.uSpin.value = s.spin;
  u.uPoint.value = s.point;
  u.uT.value = s.t;
  u.uAlpha.value = s.alpha ?? 1;
  u.uPx.value = 2015 * gl.getPixelRatio();
  return <points geometry={geo} material={mat} rotation={[s.tiltX ?? 0, s.rotY ?? 0, 0]} frustumCulled={false} />;
};

const Cam: React.FC = () => {
  const { camera } = useThree();
  const D = 540 / Math.tan((15 * Math.PI) / 180);
  camera.position.set(0, 0, D);
  camera.lookAt(0, 0, 0);
  return null;
};

export const ParticleField: React.FC<{
  th: SpecimenTheme;
  s: FieldState;
  text: { value: string; font: string };
  image: string;
  imageSize?: number;
  R?: number;
  bg?: string;
}> = ({ th, s, text, image, imageSize = 620, R = 330, bg }) => {
  const targets = useFieldTargets(text, image, imageSize);
  return (
    <ThreeCanvas resize={{ offsetSize: true, scroll: false }} width={1920} height={1080} flat camera={{ fov: 30, near: 1, far: 20000, position: [0, 0, 2015] }} style={{ position: "absolute", inset: 0 }}>
      <color attach="background" args={[bg ?? th.ink]} />
      <Cam />
      {targets && <Points th={th} s={s} targets={targets} R={R} />}
    </ThreeCanvas>
  );
};

import React, { useLayoutEffect, useRef } from "react";
import { BASE_H, BASE_W } from "./theme";

/** A drawer paints one frame of a specimen in 1920×1080 base space. */
export type Draw = (g: CanvasRenderingContext2D, t: number) => void;
export type Region = { x: number; y: number; w: number; h: number };

/** The square of base space that a square face shows when cover-fitted. */
export const SQUARE: Region = { x: (BASE_W - BASE_H) / 2, y: 0, w: BASE_H, h: BASE_H };

/**
 * Renders a drawer into a canvas of any size. `region` picks the part of base space to show
 * (cover-fitted), so the same specimen can fill the screen, a grid panel, a cube face or one Rubik sticker.
 */
export const SpecimenCanvas: React.FC<{
  draw: Draw;
  t: number;
  w?: number;
  h?: number;
  region?: Region;
  res?: number;
  style?: React.CSSProperties;
}> = ({ draw, t, w = BASE_W, h = BASE_H, region = { x: 0, y: 0, w: BASE_W, h: BASE_H }, res = 1, style }) => {
  const ref = useRef<HTMLCanvasElement>(null);
  // follow the render scale (`--scale=2` for 4K) so canvases stay sharp
  const dpr = typeof window !== "undefined" ? window.devicePixelRatio || 1 : 1;
  const pw = Math.max(1, Math.round(w * res * dpr));
  const ph = Math.max(1, Math.round(h * res * dpr));
  useLayoutEffect(() => {
    const g = ref.current?.getContext("2d");
    if (!g) return;
    g.setTransform(1, 0, 0, 1, 0, 0);
    g.clearRect(0, 0, pw, ph);
    const s = Math.max(pw / region.w, ph / region.h);
    g.setTransform(s, 0, 0, s, (pw - region.w * s) / 2 - region.x * s, (ph - region.h * s) / 2 - region.y * s);
    g.save();
    draw(g, t);
    g.restore();
  });
  return <canvas ref={ref} width={pw} height={ph} style={{ width: w, height: h, display: "block", ...style }} />;
};

import React from "react";
import { AbsoluteFill, useCurrentFrame } from "remotion";
import { clamp01, mixHex, rand, timecode, type SpecimenTheme } from "./theme";

export type Chapter = { at: number; no: string; name: string; dim: string };
export type Caption = { from: number; to: number; text: string | ((f: number) => string) };

const GLYPHS = "ABCDEFGHJKLMNPQRSTUVWXYZ0123456789×·→";

/** Type-on with a short scramble for not-yet-settled characters. */
const scramble = (text: string, f: number, from: number, seed: number) => {
  const p = (f - from) / 10;
  return Array.from(text)
    .map((ch, i) => {
      if (ch === " ") return ch;
      const k = p * text.length - i;
      if (k >= 1.2) return ch;
      if (k <= 0) return " ";
      return GLYPHS[Math.floor(rand(i + Math.floor(f) * 7, seed) * GLYPHS.length)];
    })
    .join("");
};

/**
 * Spec-sheet chrome: corner marks, film title, format line, chapter number + name + dimension,
 * timecode, a progress rule with chapter ticks, and one technical caption at top centre.
 * `light` lists frame ranges with a light background (the HUD turns ink there).
 */
export const SpecimenHud: React.FC<{
  th: SpecimenTheme;
  title: string;
  spec: string | ((scale: number) => string); // a function receives the render scale (2 for 4K)
  chapters: Chapter[];
  total: number;
  fps: number;
  light?: [number, number][];
  captions?: Caption[];
  hideAt?: number;
}> = ({ th, title, spec, chapters, total, fps, light = [], captions = [], hideAt = Infinity }) => {
  const f = useCurrentFrame();
  const dpr = typeof window !== "undefined" ? window.devicePixelRatio || 1 : 1;
  const l = light.reduce((acc, [a, b]) => Math.max(acc, clamp01((f - a + 1) / 4) * clamp01((b - f + 1) / 4)), 0);
  const col = mixHex(th.cream, th.ink, l, 0.78);
  const dim = mixHex(th.cream, th.ink, l, 0.36);
  const halo = mixHex(th.ink, th.paper, l, 0.9);
  const vis = clamp01((f - 4) / 10) * (1 - clamp01((f - hideAt) / 10));
  if (vis <= 0) return null;
  const ci = Math.max(0, chapters.filter((c) => f >= c.at).length - 1);
  const ch = chapters[ci];
  const roll = clamp01((f - ch.at) / 8);
  const prev = ci > 0 ? chapters[ci - 1] : null;
  const font: React.CSSProperties = { fontFamily: th.mono, fontSize: 15, letterSpacing: "0.2em", textTransform: "uppercase", color: col, whiteSpace: "pre", textShadow: `0 0 6px ${halo}, 0 0 14px ${halo}, 0 0 22px ${halo}` };
  const mark = (s: React.CSSProperties) => <div style={{ position: "absolute", width: 22, height: 22, borderColor: col, borderStyle: "solid", borderWidth: 0, ...s }} />;
  const cap = captions.find((c) => f >= c.from && f < c.to);
  const capText = cap ? (typeof cap.text === "function" ? cap.text(f) : cap.text) : "";
  const capAlpha = cap ? clamp01((cap.to - f) / 6) : 0;
  const label = (c: Chapter) => (
    <span>
      {c.no}  {c.name}  <span style={{ color: dim }}>·  {c.dim}</span>
    </span>
  );
  const W = 1920 - 160;
  return (
    <AbsoluteFill style={{ opacity: vis, pointerEvents: "none" }}>
      {mark({ left: 44, top: 44, borderLeftWidth: 1.5, borderTopWidth: 1.5 })}
      {mark({ right: 44, top: 44, borderRightWidth: 1.5, borderTopWidth: 1.5 })}
      {mark({ left: 44, bottom: 44, borderLeftWidth: 1.5, borderBottomWidth: 1.5 })}
      {mark({ right: 44, bottom: 44, borderRightWidth: 1.5, borderBottomWidth: 1.5 })}
      <div style={{ ...font, position: "absolute", left: 80, top: 58 }}>{title}</div>
      <div style={{ ...font, position: "absolute", right: 80, top: 58 }}>{typeof spec === "function" ? spec(dpr) : spec}</div>
      <div style={{ ...font, position: "absolute", left: 80, bottom: 52, height: 20, overflow: "hidden", width: 600 }}>
        {prev && roll < 1 && <div style={{ position: "absolute", top: -20 * roll }}>{label(prev)}</div>}
        <div style={{ position: "absolute", top: prev ? 20 * (1 - roll) : 0 }}>{label(ch)}</div>
      </div>
      <div style={{ ...font, position: "absolute", right: 80, bottom: 52 }}>TC {timecode(f, fps)}</div>
      <div style={{ position: "absolute", left: 80, bottom: 40, width: W, height: 1, background: dim }} />
      <div style={{ position: "absolute", left: 80, bottom: 40, width: W * clamp01(f / total), height: 1, background: col }} />
      {chapters.map((c) => (
        <div key={c.no} style={{ position: "absolute", left: 80 + W * (c.at / total), bottom: 37, width: 1, height: 7, background: f >= c.at ? col : dim }} />
      ))}
      {cap && (
        <div style={{ ...font, textTransform: "none", position: "absolute", left: 0, right: 0, top: 118, textAlign: "center", opacity: capAlpha, color: col }}>
          {scramble(capText, f, cap.from, cap.from)}
        </div>
      )}
    </AbsoluteFill>
  );
};

import type { Draw } from "./SpecimenCanvas";
import {
  BASE_H,
  BASE_W,
  clamp01,
  easeBack,
  easeInOut,
  easeOut,
  luma,
  mix,
  mixHex,
  noise1,
  rand,
  rgba,
  type SpecimenTheme,
} from "./theme";

const fillBg = (g: CanvasRenderingContext2D, bg: string | null | undefined, fallback: string) => {
  if (bg === null) return;
  g.fillStyle = bg ?? fallback;
  g.fillRect(-4, -4, BASE_W + 8, BASE_H + 8);
};

/* ── 01 POINT: halftone dot grid with a radial wave ──────────────────────────── */

export type HalftoneOpts = {
  cols?: number;
  rows?: number;
  ox?: number; // wave origin (where the ball landed)
  oy?: number;
  spawn?: number; // radius in px that has appeared so far (grow from the origin)
  collapse?: number; // 0..1, every dot converges on (tx, ty)
  tx?: number;
  ty?: number;
  bg?: string | null;
  diverse?: number; // 0..1 share of dots that get their own colour + shape (inclusion)
};

export const HALFTONE_GRID = { cols: 48, rows: 27 };

export const drawHalftone =
  (th: SpecimenTheme, o: HalftoneOpts = {}): Draw =>
  (g, t) => {
    const cols = o.cols ?? HALFTONE_GRID.cols;
    const rows = o.rows ?? HALFTONE_GRID.rows;
    const sx = BASE_W / cols;
    const sy = BASE_H / rows;
    const ox = o.ox ?? 960;
    const oy = o.oy ?? 540;
    const tx = o.tx ?? 960;
    const ty = o.ty ?? 540;
    const spawn = o.spawn ?? 1e9;
    const collapse = o.collapse ?? 0;
    const diverse = o.diverse ?? 0;
    const cols7 = [th.cream, ...th.sprinkle];
    fillBg(g, o.bg, th.ink);
    const dmax = 2300;
    for (let j = 0; j < rows; j++) {
      for (let i = 0; i < cols; i++) {
        const x = (i + 0.5) * sx;
        const y = (j + 0.5) * sy;
        const d = Math.hypot(x - ox, y - oy);
        const appear = clamp01((spawn - d) / 110);
        if (appear <= 0) continue;
        const ph = d * 0.0165 - t * 0.19;
        const w = 0.5 + 0.5 * Math.sin(ph);
        const ring = Math.floor((ph + Math.PI / 2) / (Math.PI * 2));
        let r = (1.8 + 12 * w * w) * easeOut(appear) * Math.min(sx, sy) / 40;
        let px = x;
        let py = y;
        if (collapse > 0) {
          const k = easeInOut(clamp01(collapse * 1.6 - (1 - d / dmax) * 0.6));
          px = mix(x, tx, k);
          py = mix(y, ty, k);
          r *= 1 - 0.7 * k;
        }
        const crest = w > 0.64;
        const idx = j * cols + i;
        if (diverse > 0 && rand(idx, 61) < diverse) {
          const c = cols7[Math.floor(rand(idx, 62) * cols7.length)];
          const rr = Math.max(0.5, r * (0.8 + rand(idx, 64) * 0.5));
          g.globalAlpha = 0.55 + 0.45 * w;
          g.fillStyle = c;
          g.strokeStyle = c;
          const shape = Math.floor(rand(idx, 63) * 4);
          g.beginPath();
          if (shape === 0) g.arc(px, py, rr, 0, Math.PI * 2);
          else if (shape === 1) g.rect(px - rr * 0.88, py - rr * 0.88, rr * 1.76, rr * 1.76);
          else if (shape === 2) {
            g.moveTo(px, py - rr * 1.15);
            g.lineTo(px + rr * 1.15, py);
            g.lineTo(px, py + rr * 1.15);
            g.lineTo(px - rr * 1.15, py);
            g.closePath();
          } else {
            g.lineWidth = Math.max(1, rr * 0.38);
            g.arc(px, py, rr * 0.8, 0, Math.PI * 2);
            g.stroke();
            continue;
          }
          g.fill();
          continue;
        }
        g.globalAlpha = crest ? 1 : 0.8;
        g.fillStyle = crest ? (((ring % 2) + 2) % 2 === 0 ? th.accent : th.accent2) : th.cream;
        g.beginPath();
        g.arc(px, py, Math.max(0.4, r), 0, Math.PI * 2);
        g.fill();
      }
    }
    g.globalAlpha = 1;
    if (collapse > 0.8) {
      g.fillStyle = th.cream;
      g.beginPath();
      g.arc(tx, ty, 12 * clamp01((collapse - 0.8) / 0.2), 0, Math.PI * 2);
      g.fill();
    }
  };

/* ── 02 LINE: ridge lines (Unknown Pleasures) that can flatten into circle chords ── */

export type RidgeOpts = {
  n?: number;
  x0?: number;
  x1?: number;
  y0?: number;
  y1?: number;
  amp?: number; // 0..1 peak height
  reveal?: number; // 0..1 lines drawn left → right
  spread?: number; // 0..1 lines fan out from the centre line
  chord?: number; // 0..1 flatten into horizontal chords of a circle (hand-off to StringArt)
  R?: number;
  cx?: number;
  cy?: number;
  highlight?: number;
  bg?: string | null;
};

export const RIDGE_LINES = 48;

/** y of chord j when `n` horizontal chords fill a circle of radius R (shared with drawStrings). */
export const chordY = (j: number, n: number, R: number, cy: number) => cy - R * 0.94 + (j / (n - 1)) * R * 1.88;

export const drawRidges =
  (th: SpecimenTheme, o: RidgeOpts = {}): Draw =>
  (g, t) => {
    const n = o.n ?? RIDGE_LINES;
    const x0 = o.x0 ?? 540;
    const x1 = o.x1 ?? 1380;
    const y0 = o.y0 ?? 250;
    const y1 = o.y1 ?? 830;
    const cx = o.cx ?? 960;
    const cy = o.cy ?? 540;
    const R = o.R ?? 300;
    const amp = o.amp ?? 1;
    const reveal = o.reveal ?? 1;
    const spread = o.spread ?? 1;
    const chord = o.chord ?? 0;
    const hi = o.highlight ?? Math.floor(n / 2);
    const bg = o.bg === undefined ? th.ink : o.bg;
    fillBg(g, bg, th.ink);
    const M = 150;
    for (let i = 0; i < n; i++) {
      const u = i / (n - 1);
      const base = mix(cy, mix(y0, y1, u), easeInOut(spread));
      const yc = chordY(i, n, R, cy);
      const hl = Math.sqrt(Math.max(0, R * R - (yc - cy) * (yc - cy)));
      const yb = mix(base, yc, chord);
      const xa = mix(x0, cx - hl, chord);
      const xb = mix(x1, cx + hl, chord);
      const xr = mix(xa, xb, clamp01(reveal * 1.25 - u * 0.25));
      if (xr <= xa + 1) continue;
      const rowAmp = (0.3 + 0.7 * Math.sin(Math.PI * u)) * amp * (1 - chord);
      const ys: number[] = [];
      for (let k = 0; k <= M; k++) {
        const x = mix(xa, xr, k / M);
        const env = Math.exp(-Math.pow((x - cx) / 175, 2));
        let bumps = 0;
        for (let b = 0; b < 4; b++) {
          const c = cx + (rand(i, b) - 0.5) * 290;
          const wd = 18 + rand(i, b + 7) * 40;
          const a = rand(i, b + 13) * (0.55 + 0.45 * Math.sin(t * 0.075 + rand(i, b + 3) * 6.28));
          bumps += a * Math.exp(-Math.pow((x - c) / wd, 2));
        }
        const h = env * (bumps * 105 + 7 * noise1(x * 0.045 + i * 1.7 + t * 0.035, i)) + 1.2 * noise1(x * 0.2 + i, 3);
        ys.push(yb - h * rowAmp);
      }
      g.beginPath();
      for (let k = 0; k <= M; k++) {
        const x = mix(xa, xr, k / M);
        if (k === 0) g.moveTo(x, ys[k]);
        else g.lineTo(x, ys[k]);
      }
      if (bg) {
        g.lineTo(xr, yb + 60);
        g.lineTo(xa, yb + 60);
        g.closePath();
        g.fillStyle = bg;
        g.fill();
        g.beginPath();
        for (let k = 0; k <= M; k++) {
          const x = mix(xa, xr, k / M);
          if (k === 0) g.moveTo(x, ys[k]);
          else g.lineTo(x, ys[k]);
        }
      }
      g.strokeStyle = i === hi ? th.accent : rgba(th.cream, 0.88);
      g.lineWidth = i === hi ? 2.6 : 1.6;
      g.stroke();
    }
  };

/* ── 02 LINE: modular multiplication string art ─────────────────────────────── */

export type StringOpts = {
  n?: number;
  R?: number;
  cx?: number;
  cy?: number;
  k?: number; // multiplier: line i joins point i and point k·i (mod n)
  rot?: number;
  enter?: number; // 0..1 the 48 ridge chords swing into place
  extra?: number; // 0..1 the remaining lines fade in
  squash?: number; // 0..1 collapse into one horizontal line
  bg?: string | null;
};

export const STRING_POINTS = 200;

export const drawStrings =
  (th: SpecimenTheme, o: StringOpts = {}): Draw =>
  (g, t) => {
    const n = o.n ?? STRING_POINTS;
    const R = o.R ?? 300;
    const cx = o.cx ?? 960;
    const cy = o.cy ?? 540;
    const k = o.k ?? 2;
    const rot = o.rot ?? -Math.PI / 2 + t * 0.002;
    const enter = o.enter ?? 1;
    const extra = o.extra ?? 1;
    const squash = o.squash ?? 0;
    fillBg(g, o.bg, th.ink);
    const sq = (y: number) => cy + (y - cy) * (1 - 0.992 * easeInOut(squash));
    const cols = th.sprinkle.length >= 3 ? th.sprinkle.slice(0, 3) : [th.accent, th.accent2, th.cream];
    g.globalCompositeOperation = "lighter";
    for (let i = 0; i < n; i++) {
      const a1 = (Math.PI * 2 * i) / n + rot;
      const a2 = (Math.PI * 2 * k * i) / n + rot;
      let p1x = cx + R * Math.cos(a1);
      let p1y = cy + R * Math.sin(a1);
      let p2x = cx + R * Math.cos(a2);
      let p2y = cy + R * Math.sin(a2);
      const jf = (i * RIDGE_LINES) / n;
      const j = Math.round(jf);
      const isChord = Math.abs(jf - j) < (RIDGE_LINES / n) * 0.5 && j < RIDGE_LINES;
      let alpha = 0.5;
      if (isChord) {
        const yc = chordY(j, RIDGE_LINES, R, cy);
        const hl = Math.sqrt(Math.max(0, R * R - (yc - cy) * (yc - cy)));
        const e = easeInOut(clamp01(enter * 1.5 - rand(j, 5) * 0.5));
        p1x = mix(cx - hl, p1x, e);
        p1y = mix(yc, p1y, e);
        p2x = mix(cx + hl, p2x, e);
        p2y = mix(yc, p2y, e);
        alpha = mix(0.9, 0.5, e);
      } else {
        alpha *= clamp01(extra * 1.4 - rand(i, 9) * 0.4);
        if (alpha <= 0.01) continue;
      }
      const u = i / n;
      const c = u < 0.5 ? mixHex(cols[0], cols[1], u * 2, alpha) : mixHex(cols[1], cols[2], (u - 0.5) * 2, alpha);
      g.strokeStyle = c;
      g.lineWidth = 1.15;
      g.beginPath();
      g.moveTo(p1x, sq(p1y));
      g.lineTo(p2x, sq(p2y));
      g.stroke();
    }
    g.globalCompositeOperation = "source-over";
    g.strokeStyle = rgba(th.cream, 0.28 * (1 - squash));
    g.lineWidth = 1;
    g.beginPath();
    g.ellipse(cx, cy, R, Math.max(0.5, R * (1 - 0.992 * easeInOut(squash))), 0, 0, Math.PI * 2);
    g.stroke();
    if (squash > 0.6) {
      const e = clamp01((squash - 0.6) / 0.4);
      g.strokeStyle = rgba(th.cream, e);
      g.lineWidth = 2.2;
      g.beginPath();
      g.moveTo(cx - R, cy);
      g.lineTo(cx + R, cy);
      g.stroke();
    }
  };

/* ── 03 PLANE: a line becomes a plane becomes the brand palette ─────────────── */

export type PaletteOpts = {
  grow?: number; // 0..1 line widens, then thickens into a full-screen plane
  split?: number; // 0..1 the plane splits into swatch columns
  labels?: number; // 0..1 swatch labels type on
  exit?: number; // 0..1 columns slide away, revealing the plane again
  lineW?: number; // width of the starting line (the collapsed string art)
  under?: string; // colour revealed when the columns slide away (default: the hero plane); "none" = transparent
};

export const drawPalette =
  (th: SpecimenTheme, o: PaletteOpts = {}): Draw =>
  (g) => {
    const grow = o.grow ?? 1;
    const split = o.split ?? 0;
    const labels = o.labels ?? 0;
    const exit = o.exit ?? 0;
    // under: "none" leaves the canvas transparent behind the sliding columns (reveal a video / layer below)
    const reveal = exit > 0 && o.under === "none";
    if (!reveal) {
      g.fillStyle = th.ink;
      g.fillRect(-4, -4, BASE_W + 8, BASE_H + 8);
      const gw = mix(o.lineW ?? 600, BASE_W + 8, easeInOut(clamp01(grow / 0.45)));
      const gh = mix(2.2, BASE_H + 8, easeInOut(clamp01((grow - 0.38) / 0.62)));
      g.fillStyle = exit > 0 && o.under ? o.under : grow < 0.3 ? mixHex(th.cream, th.accent, grow / 0.3) : th.accent;
      g.fillRect(960 - gw / 2, 540 - gh / 2, gw, gh);
    }
    if (split <= 0) return;
    const sw = th.palette;
    const cw = BASE_W / sw.length;
    sw.forEach((s, i) => {
      const p = easeInOut(clamp01(split * 1.7 - i * 0.1));
      const out = easeInOut(clamp01(exit * 1.6 - i * 0.08));
      const dir = i % 2 === 0 ? -1 : 1;
      const h = p * BASE_H;
      const y = BASE_H - h + out * dir * (BASE_H + 40);
      g.fillStyle = s.hex;
      g.fillRect(i * cw - 0.5, y, cw + 1, h);
      const la = clamp01(labels * 2 - i * 0.14) * (1 - out);
      if (la <= 0) return;
      const tc = luma(s.hex) > 0.55 ? th.ink : th.cream;
      g.globalAlpha = la;
      g.fillStyle = tc;
      g.font = `500 17px ${th.mono}`;
      g.fillText(String(i + 1).padStart(2, "0"), i * cw + 26, y + BASE_H - 164);
      g.font = `600 30px ${th.sans}`;
      g.fillText(s.name, i * cw + 26, y + BASE_H - 118);
      g.font = `400 17px ${th.mono}`;
      g.fillText(s.hex.toUpperCase(), i * cw + 26, y + BASE_H - 84);
      g.globalAlpha = 1;
    });
  };

/* ── 03 PLANE: filled / outlined marquee rows ───────────────────────────────── */

export type MarqueeOpts = {
  words: string[];
  enter?: number;
  exit?: number;
  rows?: number;
  size?: number;
  bg?: string;
  ink?: string;
};

export const drawMarquee =
  (th: SpecimenTheme, o: MarqueeOpts): Draw =>
  (g, t) => {
    const rows = o.rows ?? 6;
    const size = o.size ?? 168;
    const ink = o.ink ?? th.ink;
    const enter = o.enter ?? 1;
    const exit = o.exit ?? 0;
    g.fillStyle = o.bg ?? th.accent;
    g.fillRect(-4, -4, BASE_W + 8, BASE_H + 8);
    const rh = BASE_H / rows;
    g.font = `900 ${size}px ${th.sans}`;
    g.textBaseline = "middle";
    const text = o.words.join("  •  ") + "  •  ";
    const tw = Math.max(200, g.measureText(text).width);
    for (let r = 0; r < rows; r++) {
      const dir = r % 2 === 0 ? 1 : -1;
      const ein = easeOut(clamp01(enter * 1.5 - r * 0.1));
      const eout = clamp01(exit * 1.5 - r * 0.1);
      const slide = (1 - ein) * -dir * 2400 + eout * eout * dir * 2400;
      const moving = (1 - ein) * 1.2 + (eout > 0 && eout < 1 ? 1 : 0);
      const drift = dir * t * 6.5 + r * 311;
      const x0 = (((drift % tw) + tw) % tw) - tw + slide;
      const y = r * rh + rh / 2 + size * 0.04;
      const samples = moving > 0.05 ? 6 : 1;
      for (let s = 0; s < samples; s++) {
        const off = samples > 1 ? (s / (samples - 1) - 0.5) * 140 * Math.min(1, moving) * dir : 0;
        g.globalAlpha = samples > 1 ? 1.6 / samples : 1;
        for (let x = x0; x < BASE_W + tw; x += tw) {
          if (r % 2 === 1) {
            // stroke, then fill with the background: variable fonts have overlapping contours that a bare stroke shows
            g.strokeStyle = ink;
            g.lineWidth = 6;
            g.strokeText(text, x + off, y);
            g.fillStyle = o.bg ?? th.accent;
            g.fillText(text, x + off, y);
          } else {
            g.fillStyle = ink;
            g.fillText(text, x + off, y);
          }
        }
      }
      g.globalAlpha = 1;
    }
    g.textBaseline = "alphabetic";
  };

/* ── 03 PLANE: Truchet tiles whose arcs rejoin into continuous paths ─────────── */

export type TruchetOpts = {
  size?: number;
  assemble?: number; // 0..1 tiles pop in from the centre
  hole?: number; // half-height in px of a cleared ellipse for copy
  bg?: string;
  stroke?: number;
};

export const drawTruchet =
  (th: SpecimenTheme, o: TruchetOpts = {}): Draw =>
  (g, t) => {
    const s = o.size ?? 120;
    const cols = Math.ceil(BASE_W / s);
    const rows = Math.ceil(BASE_H / s);
    const assemble = o.assemble ?? 1;
    const hole = o.hole ?? 0;
    g.fillStyle = o.bg ?? th.paper;
    g.fillRect(-4, -4, BASE_W + 8, BASE_H + 8);
    g.lineCap = "round";
    g.lineWidth = o.stroke ?? 17;
    for (let j = 0; j < rows; j++) {
      for (let i = 0; i < cols; i++) {
        const cx = (i + 0.5) * s;
        const cy = (j + 0.5) * s;
        const d = Math.hypot(cx - 960, cy - 540);
        const a = easeBack(clamp01(assemble * 1.8 - d / 1150), 1.4);
        if (a <= 0.001) continue;
        let alpha = 1;
        if (hole > 0) {
          const e = Math.pow((cx - 960) / (hole * 2.3), 2) + Math.pow((cy - 540) / hole, 2);
          alpha = clamp01((e - 0.8) / 0.2);
          if (alpha <= 0) continue;
        }
        const idx = j * cols + i;
        const o0 = rand(idx, 21) > 0.5 ? 1 : 0;
        const phase = (t - d / 13) / 30;
        let turns = o0;
        if (phase > 0) {
          const fr = phase - Math.floor(phase);
          turns += Math.floor(phase) + easeInOut(clamp01((fr - 0.55) / 0.45));
        }
        const pick = rand(idx, 33);
        g.strokeStyle = pick > 0.9 ? th.sprinkle[Math.floor(rand(idx, 44) * th.sprinkle.length)] : th.ink;
        g.globalAlpha = alpha;
        g.save();
        g.translate(cx, cy);
        g.rotate((turns * Math.PI) / 2);
        g.scale(a, a);
        g.beginPath();
        g.arc(-s / 2, -s / 2, s / 2, 0, Math.PI / 2);
        g.stroke();
        g.beginPath();
        g.arc(s / 2, s / 2, s / 2, Math.PI, Math.PI * 1.5);
        g.stroke();
        g.restore();
      }
    }
    g.globalAlpha = 1;
  };

/* ── 02 LINE: one line that trembles into a voice (listening) ───────────────── */

export type VoiceOpts = {
  grow?: number; // 0..1 a dot stretches into the line
  amp?: number; // 0..1 the line starts to speak
  x0?: number;
  x1?: number;
  cy?: number;
  bg?: string | null;
};

/** A speech-like waveform: syllable bursts on a carrier, two softer echo voices behind the main one. */
export const drawVoice =
  (th: SpecimenTheme, o: VoiceOpts = {}): Draw =>
  (g, t) => {
    const x0 = o.x0 ?? 540;
    const x1 = o.x1 ?? 1380;
    const cy = o.cy ?? 540;
    const grow = easeInOut(o.grow ?? 1);
    const amp = o.amp ?? 1;
    fillBg(g, o.bg, th.ink);
    const L = (x1 - x0) * grow;
    const xa = 960 - L / 2;
    const xb = 960 + L / 2;
    if (L < 3) {
      g.fillStyle = th.cream;
      g.beginPath();
      g.arc(960, cy, 12, 0, Math.PI * 2);
      g.fill();
      return;
    }
    const y = (x: number, layer: number) => {
      const u = clamp01((x - x0) / (x1 - x0));
      const env = Math.sin(Math.PI * u);
      const syl = Math.pow(0.5 + 0.5 * Math.sin(x * 0.011 - t * 0.2 + layer * 1.3), 2) * (0.65 + 0.35 * noise1(x * 0.004 + t * 0.02, 5 + layer));
      const car = Math.sin(x * 0.09 - t * 0.85 + layer * 1.7) * 0.6 + Math.sin(x * 0.23 - t * 1.6 + layer) * 0.3 + Math.sin(x * 0.041 + t * 0.45) * 0.4;
      return cy - env * syl * car * 120 * amp * (layer === 0 ? 1 : 0.55);
    };
    const M = 300;
    const stroke = (layer: number, color: string, width: number) => {
      g.strokeStyle = color;
      g.lineWidth = width;
      g.beginPath();
      for (let k = 0; k <= M; k++) {
        const x = mix(xa, xb, k / M);
        if (k === 0) g.moveTo(x, y(x, layer));
        else g.lineTo(x, y(x, layer));
      }
      g.stroke();
    };
    stroke(2, rgba(th.sprinkle[0] ?? th.accent2, 0.5 * amp), 1.4);
    stroke(1, rgba(th.accent, 0.55 * amp), 1.4);
    g.shadowColor = rgba(th.cream, 0.7);
    g.shadowBlur = 14;
    stroke(0, th.cream, 2.2);
    g.shadowBlur = 0;
  };

import React, { useMemo } from "react";
import { getLength, getPointAtLength } from "@remotion/paths";
import { clamp01 } from "./theme";

/** Where the pen tip is when `p` (0..1) of the total length of `paths` has been drawn in order. */
export const penAt = (paths: string[], p: number) => {
  const lens = paths.map((d) => getLength(d));
  const total = lens.reduce((a, b) => a + b, 0);
  let left = clamp01(p) * total;
  for (let i = 0; i < paths.length; i++) {
    if (left <= lens[i] || i === paths.length - 1) return getPointAtLength(paths[i], Math.min(lens[i], left));
    left -= lens[i];
  }
  return { x: 0, y: 0 };
};

/**
 * Draws SVG paths in sequence like a pen (signature, monoline script, logo strokes) with a glowing nib.
 * `erase` (0..1) removes the stroke from its start, so the line can be pulled back into the nib.
 * Coordinates are in `viewBox` units; `transform` places the drawing on the 1920×1080 frame.
 */
export const StrokeDraw: React.FC<{
  paths: string[];
  p: number;
  erase?: number;
  color: string;
  width: number; // in viewBox units
  viewBox?: string;
  transform?: string;
  nib?: number; // 0..1 nib glow strength
  nibColor?: string;
  nibR?: number; // nib radius in viewBox units
  glow?: number; // px of soft glow around the stroke
  lineCap?: "round" | "butt";
}> = ({ paths, p, erase = 0, color, width, viewBox = "0 0 1920 1080", transform, nib = 1, nibColor = "#fff", nibR = 6, glow = 0, lineCap = "round" }) => {
  const lens = useMemo(() => paths.map((d) => getLength(d)), [paths]);
  const total = lens.reduce((a, b) => a + b, 0);
  const drawn = clamp01(p) * total;
  const gone = clamp01(erase) * total;
  let acc = 0;
  const head = penAt(paths, erase > 0 && p >= 1 ? erase : p);
  return (
    <svg viewBox={viewBox} width={1920} height={1080} style={{ position: "absolute", inset: 0, overflow: "visible", filter: glow ? `drop-shadow(0 0 ${glow}px ${color})` : undefined }}>
      <g transform={transform}>
        {paths.map((d, i) => {
          const L = lens[i];
          const a = Math.min(L, Math.max(0, gone - acc));
          const b = Math.min(L, Math.max(0, drawn - acc));
          acc += L;
          if (b - a <= 0.01) return null;
          return <path key={i} d={d} fill="none" stroke={color} strokeWidth={width} strokeLinecap={lineCap} strokeLinejoin="round" strokeDasharray={`0 ${a} ${b - a} ${L + 1}`} />;
        })}
        {nib > 0 && (p < 1 || (erase > 0 && erase < 1)) && (
          <g opacity={nib}>
            <circle cx={head.x} cy={head.y} r={nibR * 4} fill={nibColor} opacity={0.12} />
            <circle cx={head.x} cy={head.y} r={nibR * 2} fill={nibColor} opacity={0.25} />
            <circle cx={head.x} cy={head.y} r={nibR} fill={nibColor} />
          </g>
        )}
      </g>
    </svg>
  );
};

import React, { useLayoutEffect } from "react";
import { useThree } from "@react-three/fiber";
import * as THREE from "three";
import { RoomEnvironment } from "three/examples/jsm/environments/RoomEnvironment.js";

export const StudioEnv: React.FC = () => {
  const { gl, scene } = useThree();
  useLayoutEffect(() => {
    const previous = scene.environment;
    const pm = new THREE.PMREMGenerator(gl);
    const room = new RoomEnvironment();
    const target = pm.fromScene(room, 0.04);
    scene.environment = target.texture;
    return () => {
      if (scene.environment === target.texture) scene.environment = previous;
      target.dispose();
      room.dispose();
      pm.dispose();
    };
  }, [gl, scene]);
  return null;
};

/**
 * Specimen kit (style-pack-03): shared theme and deterministic helpers.
 * Every drawer works in a 1920×1080 "base" space and is a pure function of the frame `t`.
 */

export type Swatch = { name: string; hex: string };

export type SpecimenTheme = {
  ink: string; // dark chapters
  paper: string; // light chapters
  paper2: string; // warm paper for 3D floors
  cream: string; // text / dots on ink
  accent: string; // one hero colour
  accent2: string; // warm counterpoint
  palette: Swatch[]; // brand palette shown as a specimen
  sprinkle: string[]; // supporting colours for particles / strings
  serif: string;
  sans: string;
  mono: string;
};

export const BASE_W = 1920;
export const BASE_H = 1080;

export const clamp01 = (v: number) => Math.min(1, Math.max(0, v));
export const mix = (a: number, b: number, t: number) => a + (b - a) * t;
export const smooth = (t: number) => {
  const x = clamp01(t);
  return x * x * (3 - 2 * x);
};
export const easeOut = (t: number) => 1 - Math.pow(1 - clamp01(t), 3);
export const easeInOut = (t: number) => {
  const x = clamp01(t);
  return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
};
export const easeBack = (t: number, s = 1.6) => {
  const x = clamp01(t) - 1;
  return 1 + (s + 1) * x * x * x + s * x * x;
};
/** Progress of a window [a, a + d] in frames, eased. */
export const win = (t: number, a: number, d: number, e: (x: number) => number = easeInOut) => e(clamp01((t - a) / d));

export const hash = (n: number) => {
  const x = Math.sin(n * 127.1 + 311.7) * 43758.5453123;
  return x - Math.floor(x);
};
export const rand = (i: number, salt = 0) => hash(i * 12.9898 + salt * 78.233 + salt * salt * 0.137);

/** Smooth 1D value noise in [-1, 1]. */
export const noise1 = (x: number, seed = 0) => {
  const i = Math.floor(x);
  const f = x - i;
  const u = f * f * (3 - 2 * f);
  return mix(rand(i, seed), rand(i + 1, seed), u) * 2 - 1;
};

/** Smooth 2D value noise in [-1, 1]. */
export const noise2 = (x: number, y: number, seed = 0) => {
  const xi = Math.floor(x);
  const yi = Math.floor(y);
  const xf = x - xi;
  const yf = y - yi;
  const u = xf * xf * (3 - 2 * xf);
  const v = yf * yf * (3 - 2 * yf);
  const h = (a: number, b: number) => rand(a * 57 + b * 131, seed);
  return mix(mix(h(xi, yi), h(xi + 1, yi), u), mix(h(xi, yi + 1), h(xi + 1, yi + 1), u), v) * 2 - 1;
};

const hexRgb = (hex: string): [number, number, number] => {
  const h = hex.replace("#", "");
  const n = parseInt(h.length === 3 ? h.split("").map((c) => c + c).join("") : h, 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
};
export const rgba = (hex: string, a = 1) => {
  const [r, g, b] = hexRgb(hex);
  return `rgba(${r},${g},${b},${a})`;
};
export const mixHex = (a: string, b: string, t: number, alpha = 1) => {
  const x = hexRgb(a);
  const y = hexRgb(b);
  const k = clamp01(t);
  return `rgba(${Math.round(mix(x[0], y[0], k))},${Math.round(mix(x[1], y[1], k))},${Math.round(mix(x[2], y[2], k))},${alpha})`;
};
/** Relative luminance 0..1, used to pick ink or cream labels on a swatch. */
export const luma = (hex: string) => {
  const [r, g, b] = hexRgb(hex);
  return (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255;
};

/** SMPTE-ish timecode shown in the HUD: MM:SS:FF. */
export const timecode = (f: number, fps: number) => {
  const s = Math.floor(f / fps);
  return `${String(Math.floor(s / 60)).padStart(2, "0")}:${String(s % 60).padStart(2, "0")}:${String(Math.floor(f % fps)).padStart(2, "0")}`;
};

import React, { useLayoutEffect, useMemo, useRef } from "react";
import { useThree } from "@react-three/fiber";
import { ThreeCanvas } from "@remotion/three";
import * as THREE from "three";
import { mergeVertices } from "three/examples/jsm/utils/BufferGeometryUtils.js";
import { StudioEnv } from "./StudioEnv";
import { clamp01, mix, rand, type SpecimenTheme } from "./theme";

/**
 * 04 VOLUME (three.js): a voxel height field with a radial wave, then an icosahedron that rises out of it,
 * subdivides step by step, swells into a glossy clay blob and relaxes into a sphere; finally the room goes
 * dark and only a rim light remains (hand-off to the particle sphere).
 */
export type VolumeState = {
  wave: number; // wave time in frames
  drop: number; // 0..1 voxels rain into place
  sink: number; // 0..1 centre voxels sink to make room
  field: number; // 0..1 voxel field + floor visibility
  flat?: number; // 0..1 voxels settle into a flat tiled floor (under the blob)
  rise: number; // 0..1 blob rises out of the floor
  detail: number; // icosahedron subdivision level (0 = 20 faces)
  wire: number; // 0..1 edge overlay on the faceted stages
  amp: number; // clay noise displacement
  dark: number; // 0..1 room goes dark, rim light only
  cam: { ang: number; dist: number; height: number; target: [number, number, number] };
};

export const icoFaces = (detail: number) => 20 * (detail + 1) * (detail + 1);

const N = 24;
const GAP = 1.04;
export const VOXELS = N * N;

/* 3D value noise, deterministic. */
const h3 = (x: number, y: number, z: number) => rand(x * 73.1 + y * 19.7 + z * 151.3, 4);
const n3 = (x: number, y: number, z: number) => {
  const xi = Math.floor(x);
  const yi = Math.floor(y);
  const zi = Math.floor(z);
  const s = (v: number) => v * v * (3 - 2 * v);
  const u = s(x - xi);
  const v = s(y - yi);
  const w = s(z - zi);
  const L = (a: number, b: number, t: number) => a + (b - a) * t;
  const c = (dx: number, dy: number, dz: number) => h3(xi + dx, yi + dy, zi + dz);
  return (
    L(L(L(c(0, 0, 0), c(1, 0, 0), u), L(c(0, 1, 0), c(1, 1, 0), u), v), L(L(c(0, 0, 1), c(1, 0, 1), u), L(c(0, 1, 1), c(1, 1, 1), u), v), w) * 2 - 1
  );
};

const Voxels: React.FC<{ th: SpecimenTheme; s: VolumeState }> = ({ th, s }) => {
  const ref = useRef<THREE.InstancedMesh>(null);
  const tmp = useMemo(() => new THREE.Object3D(), []);
  const col = useMemo(() => new THREE.Color(), []);
  const c0 = useMemo(() => new THREE.Color(th.paper2).multiplyScalar(0.94), [th.paper2]);
  const c1 = useMemo(() => new THREE.Color(th.accent), [th.accent]);
  const c2 = useMemo(() => new THREE.Color(th.palette.find((p) => p.name === "MOSS")?.hex ?? th.accent), [th]);
  const ink = useMemo(() => new THREE.Color(th.ink), [th.ink]);
  const warm = useMemo(() => new THREE.Color(th.accent2), [th.accent2]);
  useLayoutEffect(() => {
    const m = ref.current;
    if (!m) return;
    let k = 0;
    for (let i = 0; i < N; i++) {
      for (let j = 0; j < N; j++) {
        const x = (i - (N - 1) / 2) * GAP;
        const z = (j - (N - 1) / 2) * GAP;
        const d = Math.hypot(x, z);
        const w = 0.5 + 0.5 * Math.sin(d * 0.72 - s.wave * 0.16);
        const id = i * N + j;
        const r = rand(id, 17);
        const fall = clamp01(s.drop * 1.5 - r * 0.5);
        const sink = clamp01(s.sink * 1.6 - d / 5) * (d < 4.2 ? 1 : 0);
        const h = mix(Math.max(0.04, (0.25 + 1.7 * w * w) * (1 - sink)), 0.08, s.flat ?? 0);
        const gone = 1 - s.field;
        const y = h / 2 + (1 - fall) * (1 - fall) * 9 - sink * 0.2 - gone * (h + 0.1);
        tmp.position.set(x, y, z);
        tmp.rotation.set((1 - fall) * (r - 0.5) * 3, (1 - fall) * r * 2, 0);
        tmp.scale.set(0.9, h, 0.9);
        tmp.updateMatrix();
        m.setMatrixAt(k, tmp.matrix);
        if (r < 0.045) col.copy(ink);
        else if (r < 0.06) col.copy(warm);
        else if (w > 0.82) col.copy(c1).lerp(c2, (w - 0.82) / 0.18);
        else col.copy(c0).lerp(c1, Math.min(1, (w * w) / 0.67));
        m.setColorAt(k, col);
        k++;
      }
    }
    m.instanceMatrix.needsUpdate = true;
    if (m.instanceColor) m.instanceColor.needsUpdate = true;
  });
  return (
    <instancedMesh ref={ref} args={[undefined, undefined, VOXELS]} castShadow receiveShadow visible={s.field > 0.01}>
      <boxGeometry args={[1, 1, 1]} />
      <meshStandardMaterial roughness={0.62} metalness={0} />
    </instancedMesh>
  );
};

const Blob: React.FC<{ th: SpecimenTheme; s: VolumeState; clay: string }> = ({ th, s, clay }) => {
  const R = 2.2;
  const faceted = s.amp <= 0 && s.detail < 8;
  const lowDetail = faceted ? Math.min(7, Math.max(0, Math.round(s.detail))) : 0;
  const lowGeo = useMemo(() => new THREE.IcosahedronGeometry(R, lowDetail), [lowDetail]);
  const edges = useMemo(() => new THREE.EdgesGeometry(lowGeo, 1), [lowGeo]);
  const smooth = useMemo(() => {
    const source = new THREE.IcosahedronGeometry(R, 40);
    const g = mergeVertices(source);
    source.dispose();
    g.computeVertexNormals();
    return { g, base: Float32Array.from(g.attributes.position.array as Float32Array) };
  }, []);
  useLayoutEffect(() => {
    if (faceted) return;
    const pos = smooth.g.attributes.position.array as Float32Array;
    const b = smooth.base;
    const t = s.wave * 0.02;
    for (let i = 0; i < pos.length; i += 3) {
      const x = b[i] / R;
      const y = b[i + 1] / R;
      const z = b[i + 2] / R;
      const n = n3(x * 1.7 + t, y * 1.7 + 3.1, z * 1.7 - t) * 0.7 + n3(x * 3.6 - t, y * 3.6, z * 3.6 + 7.7) * 0.3;
      const k = 1 + s.amp * n;
      pos[i] = b[i] * k;
      pos[i + 1] = b[i + 1] * k;
      pos[i + 2] = b[i + 2] * k;
    }
    smooth.g.attributes.position.needsUpdate = true;
    smooth.g.computeVertexNormals();
  });
  useLayoutEffect(() => () => { lowGeo.dispose(); edges.dispose(); }, [lowGeo, edges]);
  useLayoutEffect(() => () => smooth.g.dispose(), [smooth]);
  const y = mix(-2.6, R + 0.55, s.rise);
  return (
    <group position={[0, y, 0]} rotation={[0.3, s.wave * 0.012, 0]} visible={s.rise > 0.001}>
      <mesh geometry={faceted ? lowGeo : smooth.g} castShadow>
        <meshPhysicalMaterial color={clay} roughness={0.42} clearcoat={1} clearcoatRoughness={0.18} flatShading={faceted} envMapIntensity={1.4} />
      </mesh>
      {faceted && s.wire > 0.01 && (
        <lineSegments geometry={edges}>
          <lineBasicMaterial color={th.ink} transparent opacity={0.4 * s.wire} />
        </lineSegments>
      )}
    </group>
  );
};

const Rig: React.FC<{ s: VolumeState; bg: THREE.Color }> = ({ s, bg }) => {
  const { camera, scene } = useThree();
  const { ang, dist, height, target } = s.cam;
  camera.position.set(target[0] + Math.sin(ang) * dist, target[1] + height, target[2] + Math.cos(ang) * dist);
  camera.lookAt(target[0], target[1], target[2]);
  scene.background = bg;
  scene.environmentIntensity = mix(0.32, 0, s.dark);
  if (!scene.fog) scene.fog = new THREE.Fog(bg.getHex(), 34, 70);
  (scene.fog as THREE.Fog).color.copy(bg);
  return null;
};

export const VolumeScene: React.FC<{ th: SpecimenTheme; s: VolumeState; clay?: string; width?: number; height?: number }> = ({ th, s, clay, width = 1920, height = 1080 }) => {
  const bg = useMemo(() => new THREE.Color(), []);
  bg.set(th.paper2).lerp(new THREE.Color(th.ink), s.dark);
  const lit = 1 - s.dark;
  const floorCol = useMemo(() => new THREE.Color(th.paper2), [th.paper2]);
  // lights for the dark stage are placed relative to the camera: a hard side key (half-moon) and a rim from behind
  const { ang, target } = s.cam;
  const d = new THREE.Vector3(Math.sin(ang), 0, Math.cos(ang));
  const right = new THREE.Vector3().crossVectors(new THREE.Vector3(0, 1, 0), d).normalize();
  const tv = new THREE.Vector3(...target);
  const side = tv.clone().addScaledVector(right, -8).addScaledVector(d, -6).add(new THREE.Vector3(0, 3.5, 0));
  const rim = tv.clone().addScaledVector(d, -10).addScaledVector(right, 3).add(new THREE.Vector3(0, 3, 0));
  return (
    <ThreeCanvas resize={{ offsetSize: true, scroll: false }} width={width} height={height} shadows="soft" flat camera={{ fov: 32, near: 0.1, far: 200, position: [0, 20, 20] }} style={{ position: "absolute", inset: 0 }}>
      <StudioEnv />
      <Rig s={s} bg={bg} />
      <hemisphereLight args={["#ffffff", th.paper2, 0.5 * lit]} />
      <ambientLight intensity={0.06 * lit} />
      <directionalLight
        castShadow
        position={[9, 18, 7]}
        intensity={2.2 * lit + 0.03}
        shadow-mapSize={[2048, 2048]}
        shadow-camera-left={-16}
        shadow-camera-right={16}
        shadow-camera-top={16}
        shadow-camera-bottom={-16}
        shadow-bias={-0.0006}
        shadow-radius={6}
      />
      <directionalLight position={side.toArray()} intensity={3.2 * s.dark} color={th.cream} />
      <directionalLight position={rim.toArray()} intensity={2.4 * s.dark} color={th.accent2} />
      <mesh rotation={[-Math.PI / 2, 0, 0]} receiveShadow visible={s.field > 0.01}>
        <planeGeometry args={[200, 200]} />
        <meshStandardMaterial color={floorCol} roughness={1} transparent opacity={s.field} />
      </mesh>
      <Voxels th={th} s={s} />
      <Blob th={th} s={s} clay={clay ?? th.accent} />
    </ThreeCanvas>
  );
};

import React from 'react';
import {AbsoluteFill} from 'remotion';
import {keyedRandom} from '../motion-core.mjs';
import {clamp01,positive,smooth,unit} from '../remotion-kit/time';
export type Presentation=(progress:number)=>{outStyle:React.CSSProperties;inStyle:React.CSSProperties};
// Incoming is composited OVER an opaque outgoing scene. Fading both to .5 leaks ground.
export const crossfade:Presentation=p=>({outStyle:{opacity:1},inStyle:{opacity:clamp01(p)}});
export const fadeThrough:Presentation=p=>({outStyle:{opacity:1-clamp01(p*2)},inStyle:{opacity:clamp01(p*2-1)}});
export function directionalWipe(direction:'left'|'right'|'up'|'down'='left',softness=.08):Presentation{
  if(softness<0||softness>.5)throw new Error('softness must be 0..0.5');
  return raw=>{
    const p=clamp01(raw);if(p===0)return {outStyle:{},inStyle:{opacity:0}};if(p===1)return {outStyle:{},inStyle:{}};
    const axis={left:'to left',right:'to right',up:'to top',down:'to bottom'}[direction];
    const edge=p*(1+2*softness)-softness;
    const mask=`linear-gradient(${axis},#000 ${(edge-softness)*100}%,transparent ${(edge+softness)*100}%)`;
    return {outStyle:{},inStyle:{maskImage:mask,WebkitMaskImage:mask}};
  };
}
export function iris(width:number,height:number,center:[number,number]=[.5,.5]):Presentation{
  positive(width);positive(height);const [x,y]=[center[0]*width,center[1]*height];
  const radius=Math.max(...[[0,0],[width,0],[0,height],[width,height]].map(([a,b])=>Math.hypot(a-x,b-y)))+1;
  return raw=>{const p=clamp01(raw);return {outStyle:{},inStyle:p===0?{opacity:0}:p===1?{}:{clipPath:`circle(${radius*p}px at ${x}px ${y}px)`}};};
}
export function push(direction:'left'|'right'|'up'|'down'='left',moveOutgoing=true):Presentation{
  const [x,y]=({left:[-1,0],right:[1,0],up:[0,-1],down:[0,1]})[direction];
  return raw=>{const p=smooth(raw);return {outStyle:{transform:moveOutgoing?`translate(${x*p*100}%,${y*p*100}%)`:undefined},inStyle:{transform:`translate(${-x*(1-p)*100}%,${-y*(1-p)*100}%)`}};};
}
export function sharedAxis(axis:'x'|'y'|'z'='y',distance=80):Presentation{
  return raw=>{const p=smooth(raw),a=axis==='z'?`scale(${1+.12*p})`:`translate${axis.toUpperCase()}(${-distance*p}px)`,b=axis==='z'?`scale(${.88+.12*p})`:`translate${axis.toUpperCase()}(${distance*(1-p)}px)`;
    return {outStyle:{transform:a,opacity:1-p},inStyle:{transform:b,opacity:p}};};
}
export function zoomThrough(origin='50% 50%',factor=3):Presentation{
  positive(factor);return raw=>{const p=smooth(raw);return {outStyle:{transformOrigin:origin,transform:`scale(${Math.exp(Math.log(factor)*p)})`,opacity:1-clamp01(p*2)},inStyle:{transformOrigin:origin,transform:`scale(${Math.exp(Math.log(1/factor)*(1-p))})`,opacity:clamp01(p*2-1)}};};
}
export function pageFlip(perspective=1400):Presentation{
  positive(perspective);return raw=>{const p=smooth(raw),common:React.CSSProperties={transformOrigin:'50% 50%',backfaceVisibility:'hidden'};
    return {outStyle:{...common,transform:`perspective(${perspective}px) rotateY(${-180*p}deg)`},inStyle:{...common,transform:`perspective(${perspective}px) rotateY(${180*(1-p)}deg)`}};};
}
/** SVG mask is generated deterministically; no duplicate scene DOM per cell. */
export function gridMask(columns=12,rows=7,seed='grid',order:'random'|'diagonal'|'columns'='diagonal'):Presentation{
  if(!Number.isInteger(columns)||!Number.isInteger(rows)||columns<1||rows<1||columns*rows>4096)throw new Error('grid dimensions must total <=4096');
  const count=columns*rows;
  const cells=Array.from({length:count},(_,id)=>({id,x:id%columns,y:Math.floor(id/columns)}));
  const rank=[...cells].sort((a,b)=>{
    const score=(c:typeof a)=>order==='random'?keyedRandom(seed,c.id):order==='columns'?c.x:(c.x+c.y);
    return score(a)-score(b)||a.id-b.id;
  });
  return raw=>{const p=clamp01(raw);if(p===0)return {outStyle:{},inStyle:{opacity:0}};if(p===1)return {outStyle:{},inStyle:{}};
    const n=Math.floor(p*count),rects=rank.slice(0,n).map(c=>`<rect x="${c.x}" y="${c.y}" width="1.002" height="1.002" fill="white"/>`).join('');
    const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${columns} ${rows}" preserveAspectRatio="none">${rects}</svg>`;
    const mask=`url("data:image/svg+xml,${encodeURIComponent(svg)}")`;
    return {outStyle:{},inStyle:{maskImage:mask,WebkitMaskImage:mask,maskSize:'100% 100%',WebkitMaskSize:'100% 100%'}};
  };
}
export function whipPan(width:number,direction:1|-1=-1,maxBlur=16):Presentation{
